css:
.notredame-news-grid {
    max-width: 1440px;
    margin-left: auto;
    margin-right: auto;
    width: 100%;
    padding-left: 0 !important;
    padding-right: 0 !important;
    font-family: var(--font-family-figtree, Figtree);
}

.notredame-news-grid > .lfr-layout-structure-item-collection {
    padding-left: 60px;
    padding-right: 60px;
}

.card-blog {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 32px;
    gap: 16px;
    width: calc(30vw - 20px) !important;
    max-width: 419px;
    min-height: 319px;
    background: var(--tertiary-100);
    border-radius: 24px;
    box-sizing: border-box;
	font-family: var(--font-family-figtree, Figtree);
}

.card-blog__date {
    font-size: 12px;
    line-height: 1.5;
    color: var(--absolute-800);
    width: 66px;
    overflow: hidden;
    white-space: nowrap;
}

.card-blog__title {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.5;
    color: var(--absolute-800);
    flex-grow: 1;
    display: flex;
    align-items: start;
    justify-content: center;
    max-height: 70px;
}

.card-blog__title > div {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    width: 100%;
}

.card-blog__description {
    font-size: 16px;
    line-height: 1.5;
    color: var(--absolute-800);
    flex-grow: 1;
    display: flex;
    align-items: start;
    justify-content: center;
}

.card-blog__description > div {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    width: 100%;
}

.card-blog__link {
    font-size: 16px;
    font-weight: 600;
    color: var(--primary-700);
    text-decoration: none;
}

.card-blog__link:hover {
    text-decoration: none !important;
    color: var(--primary-700) !important;
}

.card-link {
    height: 44px;
    border-radius: 8px;
    background: transparent;
    border: 0;
    width: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.card-link:hover {
    background: var(--secondary-300);
    border: 0;
}

@media (max-width: 1439px) {
    .news-header__link-wrapper {
        display: none;
    }

    .notredame-news-grid > .lfr-layout-structure-item-collection {
        padding-left: 20px;
        padding-right: 20px;
    }
}


@media (max-width: 991px) {
    .card-blog {
        width: calc(100vw - 40px) !important;
        max-width: 100% !important;
    }
}

@media (min-width: 390px) and (max-width: 508px) {
    .card-blog {
        width: calc(100vw - 40px) !important;
    }
}

/* DESKTOP */
@media (min-width: 992px) {
    .notredame-news-grid .container-fluid {
        display: flex !important;
        flex-direction: row !important;
        flex-wrap: wrap !important;
        align-items: stretch !important;
        justify-content: center !important;
        gap: 24px !important;
    }

    .notredame-news-grid .container-fluid > .row {
        display: flex !important;
        flex: 0 0 calc(33.333% - 16px) !important;
        width: calc(33.333% - 16px) !important;
        max-width: calc(33.333% - 16px) !important;
        margin: 0 !important;
    }

    .notredame-news-grid .container-fluid > .row > .col {
        display: flex !important;
        width: 100% !important;
        max-width: 100% !important;
        flex: 0 0 100% !important;
        padding: 0 !important;
    }

    .notredame-news-grid .lfr-layout-structure-item-card-noticias {
        width: 100% !important;
    }

    .notredame-news-grid .card-blog {
        width: 100% !important;
        max-width: none !important;
        height: 100% !important;
        margin: 0 !important;
    }
}

js:
const link = fragmentElement.querySelector('[data-noticia-link]');

if (link) {
	const ajustarLink = () => {
		const href = link.getAttribute('href')?.trim();

		if (
			!href ||
			href === '#' ||
			href.includes('$[') ||
			href.startsWith('/noticias/')
		) {
			return;
		}

		// Se vier uma URL completa, recupera somente o pathname
		let slug = href;

		try {
			const url = new URL(href, window.location.origin);

			slug = url.pathname;
		}
		catch (error) {
			// Mantém o valor original
		}

		slug = slug
			.replace(/^\/+/, '')
			.replace(/^noticias\//, '')
			.replace(/\/+$/, '');

		if (slug) {
			link.setAttribute('href', `/noticias/${slug}`);
		}
	};

	// Executa imediatamente
	ajustarLink();

	// Executa novamente depois que o Liferay finalizar o mapeamento
	requestAnimationFrame(ajustarLink);
	setTimeout(ajustarLink, 100);
	setTimeout(ajustarLink, 500);

	// Observa alterações feitas pelo Liferay no href
	const observer = new MutationObserver((mutations) => {
		const hrefFoiAlterado = mutations.some(
			(mutation) =>
				mutation.type === 'attributes' &&
				mutation.attributeName === 'href'
		);

		if (hrefFoiAlterado) {
			ajustarLink();
		}
	});

	observer.observe(link, {
		attributes: true,
		attributeFilter: ['href']
	});
};

