const link = fragmentElement.querySelector('[data-noticia-link]');

if (link) {
	const ajustarLink = () => {
		const href = link.getAttribute('href')?.trim();

		if (
			!href ||
			href === '#' ||
			href.includes('$[') ||
			href.startsWith('/noticias/')
		) {
			return;
		}

		// Se vier uma URL completa, recupera somente o pathname
		let slug = href;

		try {
			const url = new URL(href, window.location.origin);

			slug = url.pathname;
		}
		catch (error) {
			// Mantém o valor original
		}

		slug = slug
			.replace(/^\/+/, '')
			.replace(/^noticias\//, '')
			.replace(/\/+$/, '');

		if (slug) {
			link.setAttribute('href', `/noticias/${slug}`);
		}
	};

	// Executa imediatamente
	ajustarLink();

	// Executa novamente depois que o Liferay finalizar o mapeamento
	requestAnimationFrame(ajustarLink);
	setTimeout(ajustarLink, 100);
	setTimeout(ajustarLink, 500);

	// Observa alterações feitas pelo Liferay no href
	const observer = new MutationObserver((mutations) => {
		const hrefFoiAlterado = mutations.some(
			(mutation) =>
				mutation.type === 'attributes' &&
				mutation.attributeName === 'href'
		);

		if (hrefFoiAlterado) {
			ajustarLink();
		}
	});

	observer.observe(link, {
		attributes: true,
		attributeFilter: ['href']
	});
};

