    align-items: center;
    justify-content: space-between;
    gap: 60px;
    width: 100%;
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 60px;
    box-sizing: border-box;
    font-family: var(--font-family-figtree, Figtree);
}

.specialist-section__content {
    display: flex;
    flex-direction: column;
    gap: 5px;
    flex: 1;
    max-width: 849px;
}


.specialist-section__content p {
    margin-bottom: 0;
}


.specialist-section__text {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.specialist-section__title{
    margin: 0;
    padding-bottom: 16px;
    font-size: 32px;
    font-weight: 600;
    line-height: 42px;
    color: #000000;
}

.specialist-section__title *{
    font-size: 32px;
    font-weight: 600;
    line-height: 42px;
    color: #000000;
	margin-bottom: 0;
}

.specialist-section__subtitle{
    color: var(--primary-600);
}

.specialist-section__description {
    margin: 0;
    padding-bottom: 24px;
    max-width: 757px;
    font-weight: 400;
    line-height: 30px;
    color: #555555;
	font-size: 18px;
}

.specialist-section__description h2 {
    color: #555555;
    font-size: 18px !important;
    font-weight: 400 !important;
}

.specialist-section__description h3 {
    color: #555555;
    font-size: 18px !important;
    font-weight: 400 !important;
}

.specialist-section__ctas {
    display: flex;
    align-items: center;
    gap: 24px;
}

.specialist-section__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 44px;
    padding: 8px 10px;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    line-height: 26px;
    text-decoration: none;
    color: #001453;
    white-space: nowrap;
}

.specialist-section__button:hover,
.specialist-section__button:focus {
    text-decoration: none;
    color: #001453;
}

.specialist-section__button--primary {
    background: #88B9D7;
    min-width: 193px;
}

.specialist-section__button--secondary {
    background: transparent;
    min-width: 210px;
}

.specialist-section__button--secondary:hover,
.specialist-section__button--secondary:focus {
    background: rgba(136, 185, 215, 0.18);
}

.specialist-section__image {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 531px;
    height: 352px;
    background: #E0E0CD;
    border-radius: 24px;
    overflow: hidden;
}

.specialist-section__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.specialist-section.specialist-section--image-only {
    display: inline-flex;
    max-width: none;
    padding: 0;
    padding-left: 60px;
    padding-right: 60px;
    vertical-align: top;
}

.specialist-section.specialist-section--image-only .specialist-section__image {
    width: 100%;
    flex: none;
    max-height: 340px;
}

@media (min-width: 390px) and (max-width: 575px) {
    .specialist-section__ctas {
        flex-direction: column !important;
    }
}

@media (max-width: 991px) {
    .specialist-section.specialist-section--image-only {
        display: column;
        width: 100%;
        margin: 0 0 24px 0;
        padding: 0 24px;
    }
    .specialist-section.specialist-section--image-only .specialist-section__image {
        width: 100%;
        height: 260px;
    }
    .specialist-section {
        flex-direction: column;
        align-items: stretch;
        gap: 32px;
        padding: 0 24px;
    }
    .specialist-section__content {
        max-width: none;
        order: 2;
    }
    .specialist-section__image {
        order: 1;
        flex: none;
        width: 100%;
        height: 260px;
    }
    .specialist-section__title {
        font-size: 28px;
        line-height: 36px;
        padding-bottom: 16px;
    }
    .specialist-section__description {
        font-size: 16px;
        line-height: 28px;
        padding-bottom: 24px;
    }
    .specialist-section__ctas {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: center;
        gap: 16px;
    }
    .specialist-section__button {
        width: 100%;
    }
    .specialist-section__title span{
		font-size: 28px !important;	
	}
	.specialist-section__description{
		font-size: 18px !important;	
	}
}

@media (max-width: 1190px) {
