}

/* ── Content ── */
.convenience-section__content {
	display: flex;
	flex-direction: column;
	gap: 24px;
	flex: 1;
	min-width: 0;
	width: 100%;
	max-width: 849px;
	overflow: hidden;
}

/* ── Text block ── */
.convenience-section__text {
	display: flex;
	flex-direction: column;
	gap: 0;
}

.convenience-section__title {
	margin: 0;
	padding-bottom: 12px;
