.convenience-section__item {
	display: flex;
	align-items: flex-start;
	gap: 16px;
	padding: 12px 12px;
	border: 1px solid var(--tertiary-300, #D1D1B7);
	border-radius: 12px;
	background: var(--tertiary-100, #EEEEE2);
	box-sizing: border-box;
	width: 100%;
	height: 140px;
	min-width: 0;
	max-width: 100%;
	transition: background 0.2s ease, border-color 0.2s ease;
	padding: 16px 16px 16px 16px;
    height: fit-content;
}

.convenience-section__item:hover {
	background: var(--tertiary-200, #D4D4C4);
	border-color: var(--tertiary-400, #B8B89E);
}

.convenience-section__item-icon {
	flex: 0 0 32px;
	width: 32px;
	height: 32px;
	display: flex;
	align-items: center;
	justify-content: center;
	margin-top: 2px;
}

.convenience-section__item-icon img {
	width: 100%;
	height: 100%;
	object-fit: contain;
}

.convenience-section__item-body {
	display: flex;
	flex-direction: column;
	gap: 6px;
	flex: 1;
	min-width: 0;
	overflow: hidden;
}

.convenience-section__item-title {
	margin: 0;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 18px;
	font-weight: 500;
	line-height: 33px;
	letter-spacing: -0.22px;
	color: var(--neutral-900, #000000);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.convenience-section__item-title:hover,
.convenience-section__item-title:focus {
	text-decoration: underline;
}

.convenience-section__item-description {
	margin: 0;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 14px;
	font-weight: 400;
	line-height: 25.5px;
	letter-spacing: 0px;
	color: var(--neutral-600, #555555);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.convenience-section__item-link {
	display: inline-flex;
	width: fit-content;
	padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
	align-items: stretch;
	gap: 4px;
	margin-top: 4px;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 16px;
	font-weight: 600;
	line-height: 26px;
	letter-spacing: 0%;
	vertical-align: middle;
	color: var(--primary-700, #001453);
	text-decoration: none;
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid transparent;
}

.convenience-section__item-link::after {
	content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M12.955%2011.9991L8.5%207.54408L9.7726%206.27148L15.5002%2011.9991L9.7726%2017.7267L8.5%2016.4541L12.955%2011.9991Z%22%20fill%3D%22%23001453%22%2F%3E%3C%2Fsvg%3E');
	display: inline-flex;
	width: 24px;
	height: 24px;
	flex-shrink: 0;
	align-items: stretch;
	justify-content: center;
}

.convenience-section__item-link:hover{
	color: var(--primary-700, #001453);
	text-decoration: none;

}

.convenience-section__item-link:focus {
	color: var(--primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid var(--Colour-ranges-Primary-primary-700, #001453);
	box-shadow: 0 0 0 2px var(--bg-white-0, #FFF), 0 0 0 4px var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
}

/* ── Image ── */
.convenience-section__image {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: none;
	width: 531px;
	min-width: 531px;
	height: 496px;
	min-height: 496px;
	background: var(--tertiary-200, #E0E0CD);
	border-radius: 24px;
	overflow: hidden;
}

.convenience-section__image img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	display: block;
}

/* ── Image left/right positioning ──
   A imagem é renderizada uma única vez no .ftl, sempre antes do
   conteúdo no DOM. A variante --image-right inverte a ordem visual
   via flex order, sem duplicar o elemento no HTML. */
.convenience-section--image-right .convenience-section__image {
	order: 1;
}

.convenience-section--image-right .convenience-section__content {
	order: 0;
}

/* ── Image-only variant ── */
.convenience-section.convenience-section--image-only {
	display: inline-flex;
	max-width: none;
	vertical-align: top;
}

/* ── Tablet (768px – 1439px) ── */
@media (min-width: 768px) and (max-width: 1439px) {
	.convenience-section {
		flex-direction: column;
		align-items: stretch;
		gap: 24px;
		padding: 0 40px;
	}

	.convenience-section__image {
		display: flex;
		order: -1;
		width: 100%;
		min-width: 0;
		height: 250px;
		min-height: unset;
		aspect-ratio: auto;
		border-radius: 16px;
	}

	.convenience-section__content {
		max-width: none;
		gap: 20px;
	}

	.convenience-section__item {
		padding: 14px 16px;
	}

	.convenience-section__title {
		font-size: 24px !important;
		line-height: 38px;
	}

	.convenience-section__title *{
		font-size: 24px !important;
		line-height: 38px;
	}

	.convenience-section__description {
		font-size: 18px;
		line-height: 28px;
	}
}

/* ── Mobile (até 767px) ── */
@media (max-width: 767px) {
	.convenience-section {
		flex-direction: column;
		align-items: stretch;
		gap: 24px;
		padding: 0 24px;
	}

	.convenience-section__image {
		display: flex;
		order: -1;
		width: 100%;
		min-width: 0;
		height: 250px;
		min-height: unset;
		aspect-ratio: auto;
		border-radius: 12px;
	}

	.convenience-section__content {
		max-width: none;
		order: 2;
		gap: 16px;
	}

	.convenience-section__title {
		font-size: 24px;
		line-height: 32px;
		padding-bottom: 8px;
	}

	.convenience-section__description {
		font-size: 18px;
		line-height: 26px;
	}

	.convenience-section__item {
		padding: 12px 14px;
	}

	.convenience-section.convenience-section--image-only {
		display: flex;
		width: 100%;
		padding: 0 24px;
	}
}

.hero-banner {
	--hero-container: 1440px;
	--hero-side-space: max(20px, calc((100vw - var(--hero-container)) / 2));
	--hero-controls-space: 20px;

	--hero-bg: #16160f;
	--hero-blue: #3c89b7;
	--hero-blue-light: #6bb8e8;

	--hero-btn-bg: #8cc4e2;
	--hero-btn-text: #061b49;
	--hero-btn-hover-bg: #061b49;
	--hero-btn-active-bg: #344bb5;

	--hero-text: #f7f4ed;
	--hero-text-muted: #f7f4ed;

	--hero-dot-active: #3c89b7;
	--hero-dot-inactive: #f7f4ed;
	--hero-dot-border: #3c89b7;

	--hero-arrow-light-bg: #eef3f8;
	--hero-arrow-dark-bg: #12263f;
	--hero-arrow-hover-bg: #12263f;
	--hero-arrow-active-bg: #8cc4e2;
	--hero-arrow-disabled-bg: #dce6f0;
	--hero-arrow-stroke-bg: #3c89b7;

	--hero-arrow-light-text: #12263f;
	--hero-arrow-dark-text: #ffffff;
	--hero-arrow-disabled-text: #ffffff;

	--hero-transition-duration: 400ms;

	position: relative;
	width: 100%;
	overflow: hidden;
	background-color: var(--hero-bg);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
}

.hero-banner * {
	box-sizing: border-box;
}

.hero-banner__viewport {
	width: 100%;
	height: 500px;
	overflow: hidden;
}

.hero-banner__track {
	display: flex;
	width: 100%;
	height: 100%;
	transition: transform var(--hero-transition-duration) ease-out;
	will-change: transform;
}

.hero-banner__track > .hero-banner__slide {
	flex: 0 0 100%;
	width: 100%;
	min-width: 100%;
	height: 100%;
}

.hero-banner__slide {
	position: relative;
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	overflow: hidden;
	background-color: var(--hero-bg);
}

.hero-banner__media {
	position: absolute;
	inset: 0;
	z-index: 0;
	width: 100%;
	height: 100%;
}

.hero-banner__bg {
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center center;
	display: block;
}

.hero-banner__overlay {
	position: absolute;
	inset: 0;
	z-index: 1;
	background: linear-gradient(90deg, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.30) 25%, rgba(0, 0, 0, 0.08) 45%, rgba(0, 0, 0, 0.00) 55%);
}

.hero-banner__content {
	position: relative;
	z-index: 2;
	width: calc(100% - (var(--hero-controls-space) * 2));
	max-width: var(--hero-container);
	margin-inline: auto;
	padding: 0;
	color: var(--hero-text);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	transform: translateY(-6px);
}

.hero-banner__title {
	margin: 0 0 24px;
	max-width: 760px;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 56px;
	font-weight: 600;
	line-height: 66px;
	letter-spacing: 0;
	color: var(--hero-text);
}

.hero-banner__title p,
.hero-banner__title h1,
.hero-banner__title h2,
.hero-banner__title h3,
.hero-banner__title div,
.hero-banner__title span {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: inherit !important;
}

.hero-banner__title strong,
.hero-banner__title b,
.hero-banner__title strong span,
.hero-banner__title b span,
.hero-banner__highlight {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: var(--hero-blue) !important;
}

.hero-banner__description {
	margin: 0 0 32px;
	max-width: 760px;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 20px;
	font-weight: 400;
	line-height: 30px;
	letter-spacing: 0;
	color: var(--hero-text-muted);
}

.hero-banner__description p,
.hero-banner__description span,
.hero-banner__description div {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: inherit !important;
}

.hero-banner__link {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	margin-top: 8px;
	color: var(--hero-blue-light, #6bb8e8);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 16px;
	font-weight: 600;
	line-height: 20px;
	transition: color 200ms ease-out;
}

.hero-banner__link span,
.hero-banner__link span a {
	color: inherit !important;
	font: inherit !important;
	text-decoration: none;
}

.hero-banner__link-icon {
	flex-shrink: 0;
	color: #88B9D7;
	transition: transform 200ms ease-out;
}

.hero-banner__link:hover,
.hero-banner__link:focus-within {
	color: var(--hero-btn-bg, #8cc4e2);
}

.hero-banner__link:hover span a,
.hero-banner__link:focus-within span a {
	text-decoration: underline;
}

.hero-banner__link:hover .hero-banner__link-icon,
.hero-banner__link:focus-within .hero-banner__link-icon {
	transform: translateX(3px);
}

.hero-banner__ctas {
	display: flex;
	align-items: center;
	gap: 24px;
	flex-wrap: nowrap;
	max-width: 100%;
	min-width: 0;
}

.hero-banner__btn {
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
	min-width: 0;
	max-width: 100%;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	text-decoration: none;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 16px;
	font-weight: 600;
	line-height: 20px;
	border-radius: 8px;
	border: none;
	cursor: pointer;
	transition:
		background-color 200ms ease-out,
		color 200ms ease-out,
		border-color 200ms ease-out,
		box-shadow 200ms ease-out;
}

.hero-banner__btn *,
.hero-banner__btn p,
.hero-banner__btn span {
	display: block;
	max-width: 100%;
	margin: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	color: inherit !important;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
}

.hero-banner__btn:hover,
.hero-banner__btn:focus {
	text-decoration: none;
	opacity: 1;
}

.hero-banner__btn:focus-visible {
	outline: 2px solid #ffffff;
	outline-offset: 3px;
}

.hero-banner__btn--primary {
  width: fit-content;
  min-width: 132px;
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	padding: 0 24px;
	background-color: var(--hero-btn-bg);
	color: var(--hero-btn-text);
	border: 1px solid var(--hero-btn-bg);
}

.hero-banner__btn--primary:hover,
.hero-banner__btn--primary:focus {
	background-color: var(--hero-btn-hover-bg);
	color: #ffffff;
	border-color: var(--hero-btn-hover-bg);
}

.hero-banner__btn--primary:active {
	background-color: var(--hero-btn-active-bg);
	color: #ffffff;
	border-color: var(--hero-btn-active-bg);
}

.hero-banner__btn--secondary {
	width: fit-content;
 	min-width: 132px;
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	background: transparent;
	color: var(--hero-text);
	padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
	border: 2px solid transparent;
	transition: all 0.3s ease-out;
}

.hero-banner__btn--secondary:hover{
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
}

.hero-banner__btn--secondary:focus {
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid var(--Colour-ranges-Primary-primary-700, #001453);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
	box-shadow: 0 0 0 2px var(--bg-white-0, #FFF), 0 0 0 4px var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
}

.hero-banner__btn--secondary:active {
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
}

.hero-banner__arrow {
	position: absolute;
	bottom: 36px;
	z-index: 3;
	width: 32px;
	height: 33px;
	display: flex;
	align-items: center;
	justify-content: center;
	border: 1px solid transparent;
	border-radius: 4px;
	cursor: pointer;
	padding: 0;
	opacity: 1;
	transition:
		background-color 200ms ease-out,
		color 200ms ease-out,
		border-color 200ms ease-out,
		opacity 200ms ease-out;
}

.hero-banner__arrow--prev {
	right: calc(var(--hero-controls-space) + 44px);
	background-color: var(--hero-arrow-light-bg);
	color: var(--hero-arrow-light-text);
	border-color: var(--hero-arrow-light-bg);
}

.hero-banner__arrow--next {
	right: var(--hero-controls-space);
	background-color: var(--hero-arrow-dark-bg);
	color: var(--hero-arrow-dark-text);
	border-color: var(--hero-arrow-dark-bg);
}

.hero-banner__arrow:hover,
.hero-banner__arrow:focus {
	background-color: var(--hero-arrow-hover-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-hover-bg);
	opacity: 1;
}

.hero-banner__arrow:active {
	background-color: var(--hero-arrow-active-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-active-bg);
	opacity: 1;
}

.hero-banner__arrow:disabled,
.hero-banner__arrow.is-disabled {
	background-color: var(--hero-arrow-disabled-bg);
	color: var(--hero-arrow-disabled-text);
	border-color: var(--hero-arrow-disabled-bg);
	cursor: not-allowed;
	opacity: 1;
}

.hero-banner__arrow--stroke {
	background-color: transparent;
	color: var(--hero-arrow-stroke-bg);
	border-color: var(--hero-arrow-stroke-bg);
}

.hero-banner__arrow--stroke:hover,
.hero-banner__arrow--stroke:focus {
	background-color: var(--hero-arrow-stroke-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-stroke-bg);
}

.hero-banner__arrow svg {
	display: block;
	width: 8px;
	height: 14px;
}

.hero-banner__dots {
	position: absolute;
	left: var(--hero-controls-space);
	bottom: 36px;
	z-index: 3;
	display: flex;
	align-items: center;
	gap: 8px;
}

.hero-banner__dot {
	width: 10px;
	height: 10px;
	min-width: 10px;
	min-height: 10px;
	border-radius: 2px;
	border: 1px solid var(--hero-dot-border);
	background-color: var(--hero-dot-inactive);
	cursor: pointer;
	padding: 0;
	opacity: 1;
	transition:
		background-color 200ms ease-out,
		border-color 200ms ease-out,
		opacity 200ms ease-out;
}

.hero-banner__dot.is-active {
	width: 10px;
	height: 10px;
	background-color: var(--hero-dot-active);
	border-color: var(--hero-dot-active);
}

.hero-banner__arrow[hidden],
.hero-banner__dots[hidden] {
	display: none !important;
}

.hero-banner.hero-banner--edit-mode {
	overflow: hidden;
}

.hero-banner.hero-banner--edit-mode .hero-banner__viewport {
	height: 500px !important;
	min-height: 500px !important;
	overflow-y: auto;
	overflow-x: hidden;
}

.hero-banner.hero-banner--edit-mode .hero-banner__track {
	display: block;
	height: auto;
	transform: none !important;
	transition: none;
}

.hero-banner.hero-banner--edit-mode .hero-banner__slide {
	height: 500px !important;
	min-height: 500px !important;
	margin-bottom: 16px;
}

.hero-banner.hero-banner--edit-mode .hero-banner__arrow,
.hero-banner.hero-banner--edit-mode .hero-banner__dots {
	display: none !important;
}

/* Tablet */
@media (max-width: 1024px) {
	.hero-banner {
		--hero-side-space: 20px;
		--hero-controls-space: 20px;
	}

	.hero-banner__viewport {
		height: 800px;
	}

	.hero-banner__slide {
		align-items: flex-start;
		padding-top: 40px;
		padding-bottom: 0;
	}

	.hero-banner__content {
		transform: none;
	}

	.hero-banner__title {
		max-width: 720px;
		margin-bottom: 20px;
		font-size: 56px;
		line-height: 58px;
	}

	.hero-banner__description {
		max-width: 680px;
		margin-bottom: 28px;
		font-size: 20px;
		line-height: 24px;
	}

	.hero-banner__ctas {
		gap: 28px;
	}

	.hero-banner__btn {
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		font-size: 16px;
		line-height: 20px;
	}

	.hero-banner__btn--primary {
		width: fit-content;
		min-width: 162px;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		padding: 0 24px;
	}

	.hero-banner__btn--secondary {
	    width: fit-content;
		min-width: 162px;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		padding: 0;
	}

	.hero-banner__overlay {
		background: linear-gradient(
			180deg,
			rgba(22, 22, 15, 0.78) 0%,
			rgba(22, 22, 15, 0.82) 45%,
			rgba(22, 22, 15, 0.98) 100%
		);
	}

	.hero-banner__arrow {
		bottom: 34px;
	}

	.hero-banner__arrow--prev {
		right: calc(var(--hero-controls-space) + 44px);
	}

	.hero-banner__arrow--next {
		right: var(--hero-controls-space);
	}

	.hero-banner__dots {
		left: var(--hero-controls-space);
		bottom: 45px;
	}

	.hero-banner.hero-banner--edit-mode .hero-banner__viewport {
		height: 800px !important;
		min-height: 800px;
		overflow-y: auto;
		overflow-x: hidden;
	}

	.hero-banner.hero-banner--edit-mode .hero-banner__slide {
		height: 800px !important;
		min-height: 800px !important;
	}
}

@media (max-width: 768px) {
	.hero-banner {
