		font-size: 20px;
		line-height: 23px;
	}

	.hero-banner__btn {
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		font-size: 16px;
		line-height: 20px;
	}

	.hero-banner__btn--primary {
		width: 162px;
		min-width: 162px;
		max-width: 162px;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		padding: 0 24px;
	}

	.hero-banner__btn--secondary {
		width: fit-content;
    min-width: 132px;
    max-width: fit-content;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		padding: 0;
	}
