	}

	.hero-banner__slide {
		align-items: flex-start;
		padding-top: 32px;
		padding-bottom: 0;
	}

	.hero-banner__content {
		transform: none;
	}

	.hero-banner__title {
		max-width: 100%;
		margin-bottom: 18px;
		font-size: 32px !important;
		line-height: 34px !important;
		font-weight: 600 !important;
		letter-spacing: 0 !important;
	}

	.hero-banner__description {
		max-width: 100%;
		margin-bottom: 24px;
		font-size: 20px !important;
		line-height: 24px !important;
		font-weight: 400 !important;
	}

	.hero-banner__ctas {
		flex-direction: column;
		align-items: stretch;
		gap: 14px;
		width: 100%;
	}

	.hero-banner__btn {
		width: 100%;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		font-size: 16px;
		line-height: 20px;
	}

	.hero-banner__btn--primary {
		width: 100%;
		min-width: 0;
		max-width: 100%;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		padding: 0 20px;
	}

	.hero-banner__btn--secondary {
		width: 100%;
		padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
		min-width: 0;
		max-width: 100%;
		height: 44px !important;
		min-height: 44px !important;
		max-height: 44px !important;
		justify-content: center;
	}

	.hero-banner__dots {
		left: var(--hero-controls-space);
		bottom: 30px;
		gap: 7px;
	}

	.hero-banner__dot,
	.hero-banner__dot.is-active {
		width: 8px;
		height: 8px;
		min-width: 8px;
		min-height: 8px;
	}

	.hero-banner__arrow {
		bottom: 20px;
		width: 32px;
		height: 32px;
	}

	.hero-banner__arrow--prev {
		right: calc(var(--hero-controls-space) + 42px);
	}

	.hero-banner__arrow--next {
		right: var(--hero-controls-space);
	}

	.hero-banner.hero-banner--edit-mode .hero-banner__viewport {
		height: 595px !important;
		min-height: 595px;
		overflow-y: auto;
		overflow-x: hidden;
	}

	.hero-banner.hero-banner--edit-mode .hero-banner__slide {
		height: 595px !important;
		min-height: 595px !important;
	}
}

@media (max-width: 360px) {
	.hero-banner__title {
		font-size: 24px !important;
		line-height: 31px !important;
	}

	.hero-banner__description {
		font-size: 15px !important;
		line-height: 23px !important;
	}
}

js:
(function () {
	var root = fragmentElement.querySelector('.hero-banner');

	if (!root) {
		return;
	}

	if (root.dataset.heroBannerInitialized === 'true') {
		return;
	}

	root.dataset.heroBannerInitialized = 'true';

	var maxSlides = 5;
	var maxPrimaryCtaCharacters = 20;
	var maxSecondaryCtaCharacters = 20;

	var track = root.querySelector('.hero-banner__track');
	var dotsContainer = root.querySelector('.hero-banner__dots');
	var prevBtn = root.querySelector('.hero-banner__arrow--prev');
	var nextBtn = root.querySelector('.hero-banner__arrow--next');

	if (!track) {
		return;
	}

	function normalizeText(value) {
		return String(value || '').replace(/\s+/g, ' ').trim();
	}

	function limitText(value, maxLength) {
		var text = normalizeText(value);
		var chars = typeof Array.from === 'function' ? Array.from(text) : text.split('');

		if (chars.length <= maxLength) {
			return text;
		}

		return chars.slice(0, maxLength).join('').trim();
	}

	function getCtaMaxCharacters(button) {
		if (button.classList.contains('hero-banner__btn--primary')) {
			return maxPrimaryCtaCharacters;
		}

		return maxSecondaryCtaCharacters;
	}

	function limitCtaButton(button) {
		if (!button) {
			return;
		}

		var maxCharacters = getCtaMaxCharacters(button);
		var currentText = normalizeText(button.textContent);
		var limitedText = limitText(currentText, maxCharacters);

		if (currentText !== limitedText) {
			button.textContent = limitedText;
		}

		if (limitedText) {
			button.setAttribute('title', limitedText);
			button.setAttribute('aria-label', limitedText);
		}
		else {
			button.removeAttribute('title');
			button.removeAttribute('aria-label');
		}

		button.setAttribute('data-max-characters', maxCharacters);
	}

	function applyCtaLimits(scope) {
		if (!scope) {
			return;
		}

		var buttons = scope.querySelectorAll(
			'.hero-banner__btn--primary, .hero-banner__btn--secondary'
		);

		Array.prototype.forEach.call(buttons, function (button) {
			limitCtaButton(button);
		});
	}

	function bindCtaLimits() {
		var events = ['input', 'keyup', 'paste', 'blur'];

		events.forEach(function (eventName) {
			root.addEventListener(
				eventName,
				function (event) {
					var target = event.target;

					if (!target || !target.closest) {
						return;
					}

					var button = target.closest(
						'.hero-banner__btn--primary, .hero-banner__btn--secondary'
					);

					if (!button || !root.contains(button)) {
						return;
					}

					setTimeout(function () {
						limitCtaButton(button);
					}, 0);
				},
				true
			);
		});
	}

	function observeCtaLimits() {
		if (typeof MutationObserver !== 'function') {
			return;
		}

		var timer = null;

		var observer = new MutationObserver(function () {
			clearTimeout(timer);

			timer = setTimeout(function () {
				applyCtaLimits(root);
			}, 50);
		});

		observer.observe(root, {
			childList: true,
			subtree: true,
			characterData: true
		});
	}

	function isEditMode() {
		return (
			document.body.classList.contains('has-edit-mode-menu') ||
			document.documentElement.classList.contains('has-edit-mode-menu') ||
			!!document.querySelector('.page-editor__sidebar') ||
			!!document.querySelector('.page-editor__topper') ||
			!!document.querySelector('.page-editor__toolbar') ||
			!!document.querySelector('.page-editor__page-structure')
		);
	}

	function getSourceSlides() {
		return Array.prototype.slice.call(
			root.querySelectorAll('.hero-banner__slide')
		).filter(function (slide) {
			return slide.closest('.hero-banner') === root;
		});
	}

	bindCtaLimits();
	observeCtaLimits();
	applyCtaLimits(root);

	if (isEditMode()) {
		root.classList.add('hero-banner--edit-mode');

		if (prevBtn) {
			prevBtn.hidden = true;
		}

		if (nextBtn) {
			nextBtn.hidden = true;
		}

		if (dotsContainer) {
			dotsContainer.hidden = true;
		}

		return;
	}

	var attempts = 0;
	var maxAttempts = 20;

	function initCarousel() {
		var sourceSlides = getSourceSlides();

		if (!sourceSlides.length && attempts < maxAttempts) {
			attempts++;

			setTimeout(initCarousel, 100);

			return;
		}

		if (!sourceSlides.length) {
			if (prevBtn) {
				prevBtn.hidden = true;
			}

			if (nextBtn) {
				nextBtn.hidden = true;
			}

			if (dotsContainer) {
				dotsContainer.hidden = true;
			}

			return;
		}

		sourceSlides = sourceSlides.slice(0, maxSlides);

		var clonedSlides = sourceSlides.map(function (slide) {
			var clonedSlide = slide.cloneNode(true);

			applyCtaLimits(clonedSlide);

			return clonedSlide;
		});

		track.innerHTML = '';

		clonedSlides.forEach(function (slide) {
			slide.classList.add('hero-banner__slide');
			slide.removeAttribute('hidden');
			track.appendChild(slide);
		});

		applyCtaLimits(track);

		var slides = Array.prototype.slice.call(track.querySelectorAll('.hero-banner__slide'));
		var totalSlides = slides.length;

		var transitionDuration = parseInt(root.getAttribute('data-transition-duration'), 10) || 400;
		var autoplayDuration = (parseInt(root.getAttribute('data-autoplay-duration'), 10) || 8) * 1000;
		var autoplayEnabled = root.getAttribute('data-autoplay') === 'true';

		var currentIndex = 0;
		var autoplayTimer = null;
		var dots = [];

		root.style.setProperty('--hero-transition-duration', transitionDuration + 'ms');

		function hideControlsIfNeeded() {
			if (totalSlides < 2) {
				if (prevBtn) {
					prevBtn.hidden = true;
				}

				if (nextBtn) {
					nextBtn.hidden = true;
				}

				if (dotsContainer) {
					dotsContainer.hidden = true;
				}
			}
		}

		function createDots() {
			if (!dotsContainer) {
				return;
			}

			dotsContainer.innerHTML = '';

			if (totalSlides < 2) {
				dotsContainer.hidden = true;
				return;
			}

			dotsContainer.hidden = false;

			slides.forEach(function (_slide, index) {
				var dot = document.createElement('button');

				dot.type = 'button';
				dot.className = 'hero-banner__dot';
				dot.setAttribute('role', 'tab');
				dot.setAttribute('aria-label', 'Ir para o slide ' + (index + 1));
				dot.setAttribute('aria-selected', index === 0 ? 'true' : 'false');

				dot.addEventListener('click', function () {
					goToSlide(index);
					resetAutoplay();
				});

				dotsContainer.appendChild(dot);
				dots.push(dot);
			});
		}

		function getFocusableElements(slide) {
			return slide.querySelectorAll(
				'a, button, input, select, textarea, [tabindex], .hero-banner__title, .hero-banner__description'
			);
		}

		function storeOriginalTabindex(element) {
			if (element.dataset.heroOriginalTabindex !== undefined) {
				return;
			}

			if (element.hasAttribute('tabindex')) {
				element.dataset.heroOriginalTabindex = element.getAttribute('tabindex');
			}
			else {
				element.dataset.heroOriginalTabindex = '';
			}
		}

		function restoreOriginalTabindex(element) {
			if (element.dataset.heroOriginalTabindex === undefined) {
				return;
			}

			if (element.dataset.heroOriginalTabindex === '') {
				element.removeAttribute('tabindex');
			}
			else {
				element.setAttribute('tabindex', element.dataset.heroOriginalTabindex);
			}

			delete element.dataset.heroOriginalTabindex;
		}

		function updateAccessibility() {
			slides.forEach(function (slide, index) {
				var isActive = index === currentIndex;

				slide.setAttribute('aria-hidden', isActive ? 'false' : 'true');

				var focusableElements = getFocusableElements(slide);

				Array.prototype.forEach.call(focusableElements, function (element) {
					if (isActive) {
						restoreOriginalTabindex(element);

						if (
							element.classList.contains('hero-banner__title') ||
							element.classList.contains('hero-banner__description')
						) {
							element.setAttribute('tabindex', '0');
						}
					}
					else {
						storeOriginalTabindex(element);
						element.setAttribute('tabindex', '-1');
					}
				});
			});

			dots.forEach(function (dot, index) {
				var isActive = index === currentIndex;

				dot.classList.toggle('is-active', isActive);
				dot.setAttribute('aria-selected', isActive ? 'true' : 'false');
			});
		}

		function goToSlide(index) {
			currentIndex = (index + totalSlides) % totalSlides;

			track.style.transform = 'translateX(-' + currentIndex * 100 + '%)';

			updateAccessibility();
		}

		function nextSlide() {
			goToSlide(currentIndex + 1);
		}

		function prevSlide() {
			goToSlide(currentIndex - 1);
		}

		function startAutoplay() {
			if (!autoplayEnabled || totalSlides < 2) {
				return;
			}

			stopAutoplay();

			autoplayTimer = setInterval(function () {
				nextSlide();
			}, autoplayDuration);
		}

		function stopAutoplay() {
			if (autoplayTimer) {
				clearInterval(autoplayTimer);
				autoplayTimer = null;
			}
		}

		function resetAutoplay() {
			stopAutoplay();
			startAutoplay();
		}

		if (nextBtn) {
			nextBtn.hidden = totalSlides < 2;

			nextBtn.addEventListener('click', function () {
				nextSlide();
				resetAutoplay();
			});
		}

		if (prevBtn) {
			prevBtn.hidden = totalSlides < 2;

			prevBtn.addEventListener('click', function () {
				prevSlide();
				resetAutoplay();
			});
		}

		root.addEventListener('mouseenter', stopAutoplay);
		root.addEventListener('mouseleave', startAutoplay);

		root.addEventListener('focusin', stopAutoplay);
		root.addEventListener('focusout', startAutoplay);

		root.addEventListener('keydown', function (event) {
			if (totalSlides < 2) {
				return;
			}

			if (event.key === 'ArrowRight') {
				event.preventDefault();
				nextSlide();
				resetAutoplay();
			}

			if (event.key === 'ArrowLeft') {
				event.preventDefault();
				prevSlide();
				resetAutoplay();
			}
		});

		hideControlsIfNeeded();
		createDots();
		goToSlide(0);
		startAutoplay();
	}

	initCarousel();
})();

(function () {
    if (fragmentElement.__filterVisibilityInit) return;
    fragmentElement.__filterVisibilityInit = true;

    var categoryEventName = 'category-noticia-filter';
    var searchEventName = 'busca-noticia-filter';

    var categoryActive = false;
    var searchActive = false;

    function updateVisibility() {
        var hasActiveFilter = categoryActive || searchActive;
        fragmentElement.style.display = hasActiveFilter ? 'none' : '';
    }

    function handleCategoryChange(event) {
        var id = event.detail?.id;
        categoryActive = id !== null && id !== undefined && id !== '-1';
        updateVisibility();
    }

    function handleSearchChange(event) {
        var term = (event.detail?.term ?? '').trim();
        searchActive = term.length > 0;
        updateVisibility();
    }

    window.addEventListener(categoryEventName, handleCategoryChange);
    window.addEventListener(searchEventName, handleSearchChange);
})();;

css:
.nds-footer,
.nds-footer * {
	box-sizing: border-box;
	font-family: var(--font-family-figtree, Figtree);
}

.nds-footer strong {
	font-weight: 700;
}

.nds-footer {
	width: 100%;
	background: #000F42;
	color: #ffffff;
	overflow: hidden;
}

/* Container geral */
.nds-footer__wrap {
	width: 100%;
	max-width: 1198px;
	margin: 0 auto;
	padding: 40px 0;
}

/* Desktop grande - 1440px */
@media (min-width: 1400px) {
	.nds-footer__wrap {
		max-width: 1320px;
	}
}

/* Card superior */
.nds-footer__card {
	display: grid;
	grid-template-columns: minmax(320px, 430px) 1fr;
	align-items: flex-start;
	gap: 70px;
	width: 100%;
	padding: 42px 30px;
	background: #001453;
	border-radius: 12px;
}

/* CTA */
.nds-footer__cta {
	display: flex;
	flex-direction: column;
	gap: 20px;
	max-width: 430px;
}

.nds-footer__cta h2 {
	margin: 0;
	font-weight: 700;
	font-size: 32px;
	line-height: 1.35;
	letter-spacing: 0;
	color: #fff;
}

.nds-footer__cta p {
	margin: 0;
	font-weight: 400;
	font-size: 18px;
	line-height: 1.5;
	letter-spacing: 0;
	color: #fff;
}

.nds-footer__button {
	width: fit-content;
	min-width: 175px;
	min-height: 46px;
	padding: 10px 20px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	border-radius: 8px;
	background: #88B9D7;
	border: 0;
	font-weight: 700;
	font-size: 16px;
	line-height: 1.4;
	letter-spacing: 0;
	color: #001453;
	text-decoration: none;
	cursor: pointer;
}

.nds-footer__button:hover {
	background: #001453;
	color: #FFF;
	text-decoration: none;
}

.nds-footer__button:hover {
	background: #001453;
	color: #FFF;
	text-decoration: none;
}

.nds-footer__button:focus-visible {
	background: #3149A4;
	color: #FFF;
	text-decoration: none;
}

.nds-footer__button:active {
	background: #3149A4;
	color: #FFF;
	text-decoration: none;
}

/* Menus */
.nds-footer__menus {
	display: grid;
	grid-template-columns: minmax(130px, 180px) minmax(130px, 180px) minmax(210px, 1.15fr);
	gap: 27px;
	align-items: flex-start;
	width: 100%;
}

.nds-footer__menu .portlet {
	margin-bottom: 0 !important;
}

.nds-footer__menu,
.nds-footer__help {
	min-width: 0;
}

/* Ajuste para widgets de Menu Exibir dentro das drop zones */
.nds-footer__menu ul,
.nds-footer__menu .nav,
.nds-footer__menu .navbar-nav,
.nds-footer__menu .list-menu,
.nds-footer__menu .layouts-tree {
	list-style: none;
	margin: 0;
	padding: 0;
	display: grid;
	gap: 14px;
}

.nds-footer__menu li {
	margin: 0;
	padding: 0;
}

.nds-footer__menu a,
.nds-footer__menu .nav-link,
.nds-footer__menu .menu-item a,
.nds-footer__menu .layouts-tree a,
.nds-footer__menu li a {
	display: inline-block;
	max-width: 100%;
	font-weight: 400;
	font-size: 16px;
	line-height: 1.45;
	color: #ffffff;
	text-decoration: none;
	white-space: normal;
	word-break: normal;
	overflow-wrap: anywhere;
}

.nds-footer__menu a:hover,
.nds-footer__menu .nav-link:hover,
.nds-footer__menu .menu-item a:hover,
.nds-footer__menu .layouts-tree a:hover,
.nds-footer__menu li a:hover {
	color: #78BBDA;
	text-decoration: none;
}

/* Títulos dos widgets de menu, caso venham do Menu Exibir */
.nds-footer__menu h1,
.nds-footer__menu h2,
.nds-footer__menu h3,
.nds-footer__menu h4,
.nds-footer__menu .portlet-title-text,
.nds-footer__menu .navbar-text {
	margin: 0 0 16px;
	font-weight: 700;
	font-size: 20px;
	line-height: 1.4;
	color: #fff;
}

/* Bloco Precisa de ajuda */
.nds-footer__help h3 {
	margin: 0 0 18px;
	font-weight: 700;
	font-size: 18px;
	line-height: 1.4;
	letter-spacing: 0;
	color: #fff;
}

.nds-footer__help ul {
	list-style: none;
	margin: 0;
	padding: 0;
	display: grid;
	gap: 14px;
}

.nds-footer__help li {
	margin: 0;
	font-weight: 400;
	font-size: 16px;
	line-height: 1.45;
	letter-spacing: 0;
	color: #fff;
	overflow-wrap: anywhere;
}

/* Rodapé inferior */
.nds-footer__bottom {
	display: grid;
	grid-template-columns: minmax(240px, 1fr) auto minmax(240px, 1fr);
	align-items: center;
	gap: 86px;
	padding-top: 28px;
}

/* Lado esquerdo */
.nds-footer__left {
	display: grid;
	gap: 18px;
	justify-items: start;
	min-width: 0;
}

.nds-footer__social {
	list-style: none;
	margin: 0;
	padding: 0;
	display: flex;
	align-items: center;
	gap: 16px;
}

.nds-footer__social li {
	margin: 0;
	padding: 0;
}

.nds-footer__social li .nds-social__icon {
	width: 40px;
}

.nds-footer__social a {
	text-decoration: none;
	margin: 0;
}

.nds-footer__legal {
	display: grid;
	gap: 0;
}

.nds-footer__legal p {
	margin: 0;
	font-weight: 400;
	font-size: 12px;
	line-height: 1.8;
	letter-spacing: 0;
	color: #fff;
}

/* Logo central */
.nds-footer__brand {
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 0;
}

.nds-footer__logo {
	display: block;
	width: 363px;
	max-width: 100%;
	height: auto;
}

/* Lado direito */
.nds-footer__right {
	display: grid;
	gap: 16px;
	justify-items: start;
	min-width: 0;
}

.nds-footer__address {
	margin: 0;
	font-weight: 400;
	font-size: 16px;
	line-height: 1.6;
	letter-spacing: 0;
	color: #fff;
}

.nds-footer__seals {
	display: flex;
	align-items: center;
	gap: 12px;
}

.nds-footer__ans-main {
	display: block;
	width: 126px;
	height: auto;
}

.nds-footer__ans-codes {
	display: grid;
	gap: 8px;
}

.nds-footer__ans-codes img {
	display: block;
	width: 90px;
	height: auto;
}

/* Tablet - 744 / 768 */
@media (max-width: 991px) {
	.nds-footer__wrap {
		width: calc(100% - 64px);
		max-width: 704px;
