/* ---- Variáveis ---- */
.concierge-widget {
  --concierge-z: 9999;
  --concierge-panel-w: 288px;
  --concierge-panel-h: 401.5px;
  --concierge-trigger-size: 64px;
  --concierge-gap-desktop: 24px;
  --concierge-gap-mobile: 16px;
  --concierge-radius: 8px;
  --concierge-shadow: 0px 16px 32px -12px rgba(85, 85, 85, 0.7);
}

/* ============================================================
   WRAPPER — posição fixa, fora do fluxo da página
   ============================================================ */
.concierge-widget {
	position: fixed;
	bottom: 320px;
	right: 32px;
	z-index: var(--concierge-z);
	display: flex;
	flex-direction: column-reverse;
	align-items: flex-end;
	gap: 16px;
	pointer-events: none;
}

/* ============================================================
   BOTÃO FLUTUANTE (TRIGGER)
   ============================================================ */
.concierge-trigger {
  pointer-events: all;
  position: relative;
  width: var(--concierge-trigger-size);
  height: var(--concierge-trigger-size);
  border-radius: 50%;
  background: #000000;
  background-clip: padding-box;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  outline: none;
  transition: background 0.2s ease;
  flex-shrink: 0;
}

.concierge-trigger::before {
	content: "";
	position: absolute;
	inset: -5px;
	border-radius: inherit;
	background: linear-gradient(
		180deg,
		rgba(49,73,164,1) 0%,
		rgba(136,185,214,1) 50%,
		rgba(49,73,164,1) 100%
	);
	z-index: -1;
}


.concierge-trigger:focus-visible {
  outline: 2px solid #4A6FD4;
  outline-offset: 4px;
}

/* Ícone bot — visível por padrão */
.concierge-icon-bot {
  display: block;
  transition: opacity 0.15s ease;
}

/* Ícone X — visível quando aberto */
.concierge-icon-close {
  display: none;
  transition: opacity 0.15s ease;
}

/* Estado aberto */
.concierge-icon-bot-hover,
.concierge-icon-close {
	display: none;
}

/* hover fechado */
.concierge-trigger:hover .concierge-icon-bot {
	display: none;
}

.concierge-trigger:hover .concierge-icon-bot-hover {
	display: block;
}

/* aberto */
.concierge-widget.is-open .concierge-icon-bot,
.concierge-widget.is-open .concierge-icon-bot-hover {
	display: none;
}

.concierge-widget.is-open .concierge-icon-close {
	display: block;
}

/* aberto + hover continua mostrando X */
.concierge-widget.is-open .concierge-trigger:hover .concierge-icon-close {
	display: block;
}

.concierge-trigger:hover .concierge-icon-close path{
	stroke: black;
}

/* Hover: inverte as cores */
.concierge-trigger:hover {
  background: #ffffff;
}

.concierge-trigger:hover .concierge-icon-bot path,
.concierge-trigger:hover .concierge-icon-bot rect,
.concierge-trigger:hover .concierge-icon-bot circle {
  stroke: #000000;
  fill: #000000;
}

.concierge-trigger:hover .concierge-icon-bot circle {
  fill: #000000;
}

.concierge-tooltip {
  position: absolute;
  right: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  white-space: nowrap;
  background: #ffffff;
  color: #111111;
  font-family: 'Figtree', sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.4;
  padding: 10px 16px;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.12);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.18s ease, visibility 0.18s ease;
}

/* Seta da tooltip */
.concierge-tooltip::after {
  content: '';
  position: absolute;
  right: -7px;
  top: 50%;
  transform: translateY(-50%);
  border: 7px solid transparent;
  border-right: 0;
  border-left-color: #ffffff;
}

.concierge-trigger:hover .concierge-tooltip,
.concierge-trigger:focus-visible .concierge-tooltip {
  opacity: 1;
  visibility: visible;
}

/* Oculta tooltip quando aberto */
.concierge-widget.is-open .concierge-tooltip {
  display: none;
}

/* ============================================================
   PAINEL
   ============================================================ */
.concierge-panel {
  pointer-events: all;
  width: var(--concierge-panel-w);
  height: var(--concierge-panel-h);
  background: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: var(--concierge-radius);
  box-shadow: var(--concierge-shadow);
  display: flex;
  flex-direction: column;
  overflow: hidden;

  /* animação de entrada */
  opacity: 0;
  visibility: hidden;
  transform: translateY(12px) scale(0.97);
  transform-origin: bottom right;
  transition:
    opacity 0.22s ease,
    visibility 0.22s ease,
    transform 0.22s ease;
}

.concierge-widget.is-open .concierge-panel {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
}

/* ---- Header ---- */
.concierge-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: #000000;
  flex-shrink: 0;
  height: 59px;
  box-sizing: border-box;
}

.concierge-header-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.concierge-header-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.concierge-header-title {
  margin: 0;
  font-family: 'Figtree', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 18px;
  letter-spacing: -0.15px;
  color: #ffffff;
}

.concierge-header-subtitle {
  margin: 0;
  font-family: 'Figtree', sans-serif;
  font-weight: 400;
  font-size: 12px;
  line-height: 15px;
  color: #888888;
}

/* ---- Grid de cards ---- */
.concierge-grid {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 12px;
  overflow: hidden;
  box-sizing: border-box;
}

/* ---- Card ---- */
.concierge-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: 12px;
  background: var(--neutral-50);
  border: 1px solid var(--absolute-200);;
  border-radius: 8px;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}

.concierge-card:hover,
.concierge-card:focus-visible {
  border-color: #000000;
  box-shadow: 0 2px 8px rgba(0,0,0,0.10);
  text-decoration: none;
}

.concierge-card:focus-visible {
  outline: 2px solid #4A6FD4;
  outline-offset: 2px;
}

.concierge-card-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: #ffffff;
  border-radius: 10px;
  flex-shrink: 0;
  padding: 6px;
  box-sizing: border-box;
}

.concierge-card-label {
  font-family: 'Figtree', sans-serif;
  font-weight: 500;
  font-size: 12px;
  line-height: 15px;
  color: #000000;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ---- Footer ---- */
.concierge-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  background: #F9F9F9;
  border-top: 1px solid #CCCCCC;
  flex-shrink: 0;
  height: 33px;
  box-sizing: border-box;
}

.concierge-footer-text {
  margin: 0;
  font-family: 'Figtree', sans-serif;
  font-weight: 400;
  font-size: 12px;
  line-height: 16px;
  color: #4B5563;
  text-align: center;
}



/* ============================================================
   MOBILE e TABLET (até 991px)
   ============================================================ */
@media (max-width: 991px) {
  .concierge-widget {
    bottom: 150px;
    right: 32px;
    left: 0;
    align-items: end;
    flex-direction: column-reverse;
    padding-bottom: 0;
  }

  .concierge-trigger {
    margin-bottom: 16px;
  }

  .concierge-panel {
    width: calc(100% - 32px);
    height: 403px;
    border-radius: 8px 8px 0 0;
    transform-origin: bottom center;
  }

  .concierge-tooltip {
    right: auto;
    left: 0px;
    top: auto;
    bottom: calc(100% + 12px);
    transform: translateX(-50%);
  }

  .concierge-tooltip::after {
    right: auto;
    left: 65%;
    top: 100%;
    bottom: auto;
    transform: translateX(-50%);
    border: 7px solid transparent;
    border-bottom: 0;
    border-top-color: #ffffff;
  }
}

.concierge-card {
  position: relative;
}

.concierge-card-label {
  font-family: 'Figtree', sans-serif;
  font-weight: 500;
  font-size: 12px;
  line-height: 15px;
  color: #000000;
  text-decoration: none;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Expande o link para cobrir todo o card */
.concierge-card-label::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 8px;
}

body.has-edit-mode-menu .concierge-card-label::after {
  display: none;
}

.concierge-card-label:hover {
  color: #000000;
  text-decoration: none;
}

.concierge-card--optional {
  display: flex; /* visível */
}

.concierge-card--hidden {
  display: none !important;
}

.concierge-grid:has(.concierge-card--hidden:nth-child(5)):has(.concierge-card--hidden:nth-child(6)) {
  align-content: start;
}

