(function () {

  if (typeof fragmentElement === 'undefined' || !fragmentElement) return;

  const widget  = fragmentElement.querySelector('.concierge-widget');
  const trigger = fragmentElement.querySelector('.concierge-trigger');
  const panel   = fragmentElement.querySelector('.concierge-panel');

  if (!widget || !trigger || !panel) return;
  if (trigger.dataset.conciergeReady === '1') return;
  trigger.dataset.conciergeReady = '1';

  let isOpen = false;

  function openWidget() {
    isOpen = true;
    widget.classList.add('is-open');
    trigger.setAttribute('aria-expanded', 'true');
    panel.setAttribute('aria-hidden', 'false');
  }

  function closeWidget() {
    isOpen = false;
    widget.classList.remove('is-open');
    trigger.setAttribute('aria-expanded', 'false');
    panel.setAttribute('aria-hidden', 'true');
    trigger.focus();
  }

  function toggleWidget() {
    isOpen ? closeWidget() : openWidget();
  }

  /* ---- Botão trigger ---- */
  trigger.addEventListener('click', function (e) {
    e.stopPropagation();
    toggleWidget();
  });

  trigger.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleWidget();
    }
  });

  /* ---- Fechar ao clicar fora ---- */
  document.addEventListener('click', function (e) {
    if (!isOpen) return;
    if (fragmentElement.contains(e.target)) return;
    closeWidget();
  });

  /* ---- Fechar com Escape ---- */
  document.addEventListener('keydown', function (e) {
    if (isOpen && e.key === 'Escape') closeWidget();
  });

  /* ---- Painel: stopPropagation para não fechar ao clicar dentro ---- */
  panel.addEventListener('click', function (e) {
    e.stopPropagation();
  });

})();;

