(function () {
    const skiplink = document.getElementById('skiplink');

    if (!skiplink) {
        return;
    }

    const items = Array.from(
        skiplink.querySelectorAll('.br-item')
    );

    if (!items.length) {
        return;
    }

    const header =
        document.querySelector('#header') ||
        document.querySelector('header') ||
        document.querySelector('[role="banner"]');

    const focusableSelector = [
        'a[href]',
        'button:not([disabled])',
        'input:not([disabled]):not([type="hidden"])',
        'select:not([disabled])',
        'textarea:not([disabled])',
        'summary',
        'iframe',
        'audio[controls]',
        'video[controls]',
        '[contenteditable="true"]',
        '[tabindex]:not([tabindex="-1"])'
    ].join(',');

    const naturallyFocusableSelector = [
        'a[href]',
        'button:not([disabled])',
        'input:not([disabled]):not([type="hidden"])',
        'select:not([disabled])',
        'textarea:not([disabled])',
        'summary',
        'iframe',
        'audio[controls]',
        'video[controls]',
        '[contenteditable="true"]',
        '[tabindex]'
    ].join(',');

    let isOpen = false;

    function isVisible(element) {
        if (!element) {
            return false;
        }

        const style = window.getComputedStyle(element);

        return (
            style.display !== 'none' &&
            style.visibility !== 'hidden' &&
            !element.hasAttribute('hidden') &&
            element.getClientRects().length > 0
        );
    }

    function getPageFocusableElements() {
        return Array.from(
            document.querySelectorAll(focusableSelector)
        ).filter(function (element) {
            return (
                isVisible(element) &&
                !skiplink.contains(element) &&
                !element.hasAttribute('disabled') &&
                element.getAttribute('aria-hidden') !== 'true'
            );
        });
    }

    function makeFocusable(element) {
        if (!element) {
            return;
        }

        if (!element.matches(naturallyFocusableSelector)) {
            element.setAttribute('tabindex', '-1');
            element.dataset.skiplinkTemporaryFocus = 'true';
        }
    }

    function focusElement(element, preventScroll = true) {
        if (!element || !isVisible(element)) {
            return;
        }

        makeFocusable(element);

        try {
            element.focus({
                preventScroll: preventScroll
            });
        } catch (error) {
            element.focus();
        }
    }

    function focusHeader() {
        focusElement(header);
    }

    function openMenu(options = {}) {
        if (isOpen) {
            return;
        }

        const focusLastItem =
            options.focusLastItem === true;

        isOpen = true;
        skiplink.classList.add('is-visible');

        window.requestAnimationFrame(function () {
            const itemToFocus = focusLastItem
                ? items[items.length - 1]
                : items[0];

            itemToFocus.focus();
        });
    }

    function hideMenu() {
        if (!isOpen) {
            return;
        }

        isOpen = false;
        skiplink.classList.remove('is-visible');
    }

    function closeMenuAndFocusHeader() {
        hideMenu();
        focusHeader();
    }

    function closeMenuAndContinueNormalTabulation() {
        hideMenu();

        const pageFocusableElements = getPageFocusableElements();
        const next = pageFocusableElements[0] || null;

        if (next) {
            focusElement(next);
        } else {
            focusHeader();
        }
    }

    function getTargetSelector(link) {
        const href = link.getAttribute('href');

        if (!href || href === '#') {
            return null;
        }

        try {
            const url = new URL(
                href,
                window.location.href
            );

            return url.hash || null;
        } catch (error) {
            return href.startsWith('#')
                ? href
                : null;
        }
    }

    function resolveTarget(link) {
        const selector = getTargetSelector(link);

        if (!selector) {
            return null;
        }

        try {
            return document.querySelector(selector);
        } catch (error) {
            console.warn(
                `[skiplink] O seletor configurado "${selector}" é inválido.`
            );

            return null;
        }
    }

    function getFixedElementsOffset(target) {
        const fixedElements = [
            document.querySelector('#header'),
            document.querySelector('#main-searchbox')
        ];

        return fixedElements.reduce(function (total, element) {
            if (
                !element ||
                !isVisible(element) ||
                element === target ||
                element.contains(target)
            ) {
                return total;
            }

            const style = window.getComputedStyle(element);

            const isFixed =
                style.position === 'fixed' ||
                style.position === 'sticky';

            if (!isFixed) {
                return total;
            }

            return (
                total +
                element.getBoundingClientRect().height
            );
        }, 0);
    }

    function scrollAndFocusTarget(target) {
        makeFocusable(target);

        const offset = getFixedElementsOffset(target);

        const targetTop =
            target.getBoundingClientRect().top +
            window.scrollY -
            offset;

        window.scrollTo({
            top: Math.max(targetTop, 0),
            behavior: 'smooth'
        });

        window.setTimeout(function () {
            focusElement(target);
        }, 400);
    }

    function goTo(link) {
        const target = resolveTarget(link);
        const selector = getTargetSelector(link);

        const targetName =
            link.dataset.skipTo ||
            selector ||
            'destino';

        if (!target) {
            console.warn(
                `[skiplink] Nenhum elemento encontrado para "${targetName}" ` +
                `(seletor configurado: ${selector || 'não informado'}).`
            );

            closeMenuAndFocusHeader();
            return;
        }

        hideMenu();

        const skipTo = link.dataset.skipTo;


        if (skipTo === 'menu' || skipTo === 'busca') {
            focusElement(target);
            return;
        }


        scrollAndFocusTarget(target);
    }


    document.addEventListener('click', function (event) {
        const clickedElement = event.target.closest(
            'a, button, input, select, textarea, summary, ' +
            '[contenteditable="true"], [tabindex], ' +
            'main, section, article, nav, header, footer, ' +
            'div, form'
        );

        if (
            !clickedElement ||
            skiplink.contains(clickedElement)
        ) {
            return;
        }


        if (
            clickedElement.matches(
                naturallyFocusableSelector
            )
        ) {
            return;
        }

        focusElement(clickedElement);
    });

    document.addEventListener('keydown', function (event) {
        if (
            event.key !== 'Tab' ||
            isOpen
        ) {
            return;
        }

        const activeElement = document.activeElement;
        const pageFocusableElements =
            getPageFocusableElements();

        const firstFocusable =
            pageFocusableElements[0] || null;

        const lastFocusable =
            pageFocusableElements[
                pageFocusableElements.length - 1
            ] || null;

        const isInitialPageFocus =
            activeElement === document.body ||
            activeElement === document.documentElement;

        if (
            !event.shiftKey &&
            isInitialPageFocus
        ) {
            event.preventDefault();

            openMenu({
                focusLastItem: false
            });

            return;
        }

        if (
            !event.shiftKey &&
            activeElement === lastFocusable
        ) {
            event.preventDefault();

            openMenu({
                focusLastItem: false
            });

            return;
        }

        if (
            event.shiftKey &&
            activeElement === firstFocusable
        ) {
            event.preventDefault();

            openMenu({
                focusLastItem: true
            });
        }
    });

    skiplink.addEventListener('keydown', function (event) {
        if (!isOpen) {
            return;
        }

        if (event.key === 'Escape') {
            event.preventDefault();
            closeMenuAndContinueNormalTabulation();
            return;
        }

        if (event.key !== 'Tab') {
            return;
        }

        const currentIndex = items.indexOf(
            document.activeElement
        );

        if (currentIndex === -1) {
            return;
        }

        if (
            !event.shiftKey &&
            currentIndex === items.length - 1
        ) {
            event.preventDefault();
            closeMenuAndContinueNormalTabulation();
            return;
        }

        if (
            event.shiftKey &&
            currentIndex === 0
        ) {
            event.preventDefault();
            closeMenuAndFocusHeader();
        }
    });

    skiplink.addEventListener('click', function (event) {
        const link = event.target.closest('.br-item');

        if (!link) {
            return;
        }

        event.preventDefault();
        goTo(link);
    });

    document.addEventListener('click', function (event) {
        if (
            !isOpen ||
            skiplink.contains(event.target)
        ) {
            return;
        }

        closeMenuAndFocusHeader();
    });
})();;

