        border-bottom: 1px solid var(--neutral-200);
    }

    .navigation-container .submenu {
        position: static;
        width: 100%;
        min-height: inherit;
        max-height: 0;
        padding: 0;
        overflow: hidden;
        box-shadow: none;
        border: none;
        opacity: 1;
        visibility: visible;
        transition: max-height 0.4s ease, padding 0.4s ease;
        padding-left: 16px !important;
        padding-right: 16px !important;
    }

    .navigation-container .submenu.visible {
        max-height: 1200px;
        padding: 8px 0 16px;
    }

    .navigation-container .submenu ul li,
    .navigation-container .submenu ul li:last-child,
    .navigation-container .submenu ul li:not(:last-child) {
        padding-bottom: 0;
    }

    .navigation-container .secondary-link {
        flex-direction: row-reverse;
        justify-content: flex-end;
        gap: 10px;
        padding: 12px 0;
        font-size: 16px;
        white-space: normal;
        color: var(--absolute-1000, #000000);
    }

    .navigation-container .secondary-link.minha-area {
        color: var(--absolute-0, #FFFFFF);
    }

    .navigation-container .sub-submenu {
        position: static;
        width: 100%;
        min-height: inherit;
        max-height: 0;
        overflow: hidden;
        box-shadow: none;
        border: none;
        opacity: 1;
        visibility: visible;
        transition: max-height 0.4s ease;
    }

    .navigation-container .sub-submenu.visible {
        max-height: 1000px;
        border-left: 0 !important;
    }

    .navigation-container .sub-submenu ul {
        padding: 0 0 8px 30px;
    }

    .navigation-container .sub-submenu .tertiary-link {
        padding: 10px 0;
        font-size: 16px;
        white-space: normal;
    }

    .navigation-container .submenu-arrow {
        width: 20px;
        height: 20px;
        content: url('data:image/svg+xml,%3Csvg%20width%3D%2220%22%20height%3D%2220%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cpath%20d%3D%22m16.501%206.499-6.737%207-6.263-7%22%20stroke%3D%22%232D2D2D%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E');
    }

    .navigation-container .secondary-link[aria-expanded="true"] .submenu-arrow {
        width: 16px;
        height: 16px;
        content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2215.119%22%20height%3D%228.81%22%20viewBox%3D%220%200%2015.119%208.81%22%3E%3Cpath%20d%3D%22M158.476%2C424.278l6.737-7%2C6.263%2C7%22%20transform%3D%22translate(172.535%20425.338)%20rotate(180)%22%20fill%3D%22none%22%20stroke%3D%22%230435ac%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%221.5%22%2F%3E%3C%2Fsvg%3E');
        transform: rotate(180deg);
    }

    .btn-cotacao-mobile .button-styleguide.cta-primary {
        position: absolute;
        left: 0;
        top: 40px;
        width: 100%;
        border-radius: 0;
        box-shadow: 0 4px 4px rgba(0, 0, 0, 0.25);
        align-items: center;
    }

    .btn-cotacao-mobile .button-styleguide.cta-primary::after {
        content: url('data:image/svg+xml,%3Csvg%20width%3D%2220%22%20height%3D%2220%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cmask%20id%3D%22a%22%20style%3D%22mask-type%3Aalpha%22%20maskUnits%3D%22userSpaceOnUse%22%20x%3D%220%22%20y%3D%220%22%20width%3D%2220%22%20height%3D%2220%22%3E%3Cpath%20fill%3D%22%23D9D9D9%22%20d%3D%22M0%200h20v20H0z%22%2F%3E%3C%2Fmask%3E%3Cg%20mask%3D%22url(%23a)%22%3E%3Cpath%20d%3D%22M11.665%2015%2010.5%2013.792l2.958-2.959H3.332V9.167h10.125l-2.958-2.959L11.665%205l5%205-5%205Z%22%20fill%3D%22%23001453%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E');
        display: inline-block;
        width: 20px;
        height: 20px;
        flex-shrink: 0;
    }

    .btn-cotacao-mobile .button-styleguide.cta-primary:focus::after,
    .btn-cotacao-mobile .button-styleguide.cta-primary:hover::after {
        content: url('data:image/svg+xml,%3Csvg%20width%3D%2220%22%20height%3D%2220%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cmask%20id%3D%22a%22%20style%3D%22mask-type%3Aalpha%22%20maskUnits%3D%22userSpaceOnUse%22%20x%3D%220%22%20y%3D%220%22%20width%3D%2220%22%20height%3D%2220%22%3E%3Cpath%20fill%3D%22%23D9D9D9%22%20d%3D%22M0%200h20v20H0z%22%2F%3E%3C%2Fmask%3E%3Cg%20mask%3D%22url(%23a)%22%3E%3Cpath%20d%3D%22M11.667%2015%2010.5%2013.792l2.958-2.959H3.333V9.167h10.125L10.5%206.208%2011.667%205l5%205-5%205Z%22%20fill%3D%22%23fff%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E');
    }

    /* ----- Social Links ----- */
    .social-links {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 16px;
        padding: var(--spacer-4);
        margin-top: auto;
    }

    .social-links__icon {
        width: 48px;
        height: 48px;
        object-fit: contain;
        flex-shrink: 0;
    }
}

@media screen and (max-width: 767px) {
    .base-header-dropzone .menu-container {
        padding: 27px 16px;
    }

    .navigation-container {
        width: 100vw!important;
        padding: 0px!important;
        left: 0 !important;
        height: calc(100vh - 132px) !important;
    }
}

