.convenience-section {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 60px;
	width: 100%;
	max-width: 1440px;
	margin: 0 auto;
	padding: 0 60px;
	box-sizing: border-box;
	font-family: var(--font-family-figtree, Figtree);
}

/* ── Content ── */
.convenience-section__content {
	display: flex;
	flex-direction: column;
	gap: 24px;
	flex: 1;
	min-width: 0;
	width: 100%;
	max-width: 849px;
	overflow: hidden;
}

/* ── Text block ── */
.convenience-section__text {
	display: flex;
	flex-direction: column;
	gap: 0;
}

.convenience-section__title {
	margin: 0;
	padding-bottom: 12px;
	font-size: 32px;
	font-weight: 600;
	line-height: 42px;
	color: var(--neutral-900, #000000);
}

.convenience-section__subtitle {
	display: block;
	color: var(--primary-600);
}

.convenience-section__description {
	margin: 0;
	max-width: 757px;
	font-size: 18px;
	font-weight: 400;
	line-height: 30px;
	color: var(--neutral-600, #555555);
}

.convenience-section__description div {
	color: var(--neutral-600, #555555);
}

/* ── Items list ── */
.convenience-section__items {
	display: flex;
	flex-direction: column;
	gap: 12px;
	width: 100%;
	overflow: hidden;
}

/* ── Item card ── */
.convenience-section__item {
	display: flex;
	align-items: flex-start;
	gap: 16px;
	padding: 12px 12px;
	border: 1px solid var(--tertiary-300, #D1D1B7);
	border-radius: 12px;
	background: var(--tertiary-100, #EEEEE2);
	box-sizing: border-box;
	width: 100%;
	height: 140px;
	min-width: 0;
	max-width: 100%;
	transition: background 0.2s ease, border-color 0.2s ease;
	padding: 16px 16px 16px 16px;
    height: fit-content;
}

.convenience-section__item:hover {
	background: var(--tertiary-200, #D4D4C4);
	border-color: var(--tertiary-400, #B8B89E);
}

.convenience-section__item-icon {
	flex: 0 0 32px;
	width: 32px;
	height: 32px;
	display: flex;
	align-items: center;
	justify-content: center;
	margin-top: 2px;
}

.convenience-section__item-icon img {
	width: 100%;
	height: 100%;
	object-fit: contain;
}

.convenience-section__item-body {
	display: flex;
	flex-direction: column;
	gap: 6px;
	flex: 1;
	min-width: 0;
	overflow: hidden;
}

.convenience-section__item-title {
	margin: 0;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 18px;
	font-weight: 500;
	line-height: 33px;
	letter-spacing: -0.22px;
	color: var(--neutral-900, #000000);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.convenience-section__item-title:hover,
.convenience-section__item-title:focus {
	text-decoration: underline;
}

.convenience-section__item-description {
	margin: 0;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 14px;
	font-weight: 400;
	line-height: 25.5px;
	letter-spacing: 0px;
	color: var(--neutral-600, #555555);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.convenience-section__item-link {
	display: inline-flex;
	width: fit-content;
	padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
	align-items: stretch;
	gap: 4px;
	margin-top: 4px;
	font-family: var(--font-family-figtree, Figtree);
	font-size: 16px;
	font-weight: 600;
	line-height: 26px;
	letter-spacing: 0%;
	vertical-align: middle;
	color: var(--primary-700, #001453);
	text-decoration: none;
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid transparent;
}

.convenience-section__item-link::after {
	content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M12.955%2011.9991L8.5%207.54408L9.7726%206.27148L15.5002%2011.9991L9.7726%2017.7267L8.5%2016.4541L12.955%2011.9991Z%22%20fill%3D%22%23001453%22%2F%3E%3C%2Fsvg%3E');
	display: inline-flex;
	width: 24px;
	height: 24px;
	flex-shrink: 0;
	align-items: stretch;
	justify-content: center;
}

.convenience-section__item-link:hover{
	color: var(--primary-700, #001453);
	text-decoration: none;

}

.convenience-section__item-link:focus {
	color: var(--primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid var(--Colour-ranges-Primary-primary-700, #001453);
	box-shadow: 0 0 0 2px var(--bg-white-0, #FFF), 0 0 0 4px var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
}

/* ── Image ── */
.convenience-section__image {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: none;
	width: 531px;
	min-width: 531px;
	height: 496px;
	min-height: 496px;
	background: var(--tertiary-200, #E0E0CD);
	border-radius: 24px;
	overflow: hidden;
}

.convenience-section__image img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	display: block;
}

/* ── Image left/right positioning ──
   A imagem é renderizada uma única vez no .ftl, sempre antes do
   conteúdo no DOM. A variante --image-right inverte a ordem visual
   via flex order, sem duplicar o elemento no HTML. */
.convenience-section--image-right .convenience-section__image {
	order: 1;
}

.convenience-section--image-right .convenience-section__content {
	order: 0;
}

/* ── Image-only variant ── */
.convenience-section.convenience-section--image-only {
	display: inline-flex;
	max-width: none;
	vertical-align: top;
}

/* ── Tablet (768px – 1439px) ── */
@media (min-width: 768px) and (max-width: 1439px) {
	.convenience-section {
		flex-direction: column;
		align-items: stretch;
		gap: 24px;
		padding: 0 40px;
	}

	.convenience-section__image {
		display: flex;
		order: -1;
		width: 100%;
		min-width: 0;
		height: 250px;
		min-height: unset;
		aspect-ratio: auto;
		border-radius: 16px;
	}

	.convenience-section__content {
		max-width: none;
		gap: 20px;
	}

	.convenience-section__item {
		padding: 14px 16px;
	}

	.convenience-section__title {
		font-size: 24px !important;
		line-height: 38px;
	}

	.convenience-section__title *{
		font-size: 24px !important;
		line-height: 38px;
	}

	.convenience-section__description {
		font-size: 18px;
		line-height: 28px;
	}
}

/* ── Mobile (até 767px) ── */
@media (max-width: 767px) {
	.convenience-section {
		flex-direction: column;
		align-items: stretch;
		gap: 24px;
		padding: 0 24px;
	}

	.convenience-section__image {
		display: flex;
		order: -1;
		width: 100%;
		min-width: 0;
		height: 250px;
		min-height: unset;
		aspect-ratio: auto;
		border-radius: 12px;
	}

	.convenience-section__content {
		max-width: none;
		order: 2;
		gap: 16px;
	}

	.convenience-section__title {
		font-size: 24px;
		line-height: 32px;
		padding-bottom: 8px;
	}

	.convenience-section__description {
		font-size: 18px;
		line-height: 26px;
	}

	.convenience-section__item {
		padding: 12px 14px;
	}

	.convenience-section.convenience-section--image-only {
		display: flex;
		width: 100%;
		padding: 0 24px;
	}
}

js:
document.querySelectorAll('.specialist-section__button--primary, .specialist-section__button--secondary').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
        var href = btn.getAttribute('href');

        if (href && href.startsWith('#')) {
            var target = document.querySelector(href);

            if (target) {
                e.preventDefault();
                target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    });
});;

