(function () {
	var root = typeof fragmentElement !== 'undefined' && fragmentElement
		? fragmentElement
		: document;

	var list = root.querySelector('.quick-actions__list');

	if (!list) {
		return;
	}

	function normalizeText(text) {
		return (text || '').trim().replace(/\s+/g, ' ');
	}

	Array.prototype.slice.call(list.children).forEach(function (element) {
		if (!element.matches || !element.matches('a:not(.quick-actions__card)')) {
			return;
		}

		var previousCard = element.previousElementSibling;

		if (!previousCard || !previousCard.classList.contains('quick-actions__card')) {
			return;
		}

		var textElement = previousCard.querySelector('.quick-actions__text');
		var nextElement = element.nextElementSibling;

		var linkText = normalizeText(element.textContent);
		var linkHref = element.getAttribute('href');

		if (linkHref) {
			previousCard.setAttribute('href', linkHref);
		}

		if (element.getAttribute('target')) {
			previousCard.setAttribute('target', element.getAttribute('target'));
		}

		if (linkText && textElement) {
			textElement.textContent = linkText;
		}

		if (nextElement && nextElement.classList.contains('quick-actions__arrow')) {
			previousCard.appendChild(nextElement);
		}

		element.remove();
	});

	root.querySelectorAll('.quick-actions__card').forEach(function (card) {
		var textElement = card.querySelector('.quick-actions__text');

		if (!textElement) {
			return;
		}

		var nestedLink = textElement.querySelector('a[href]');

		if (nestedLink) {
			var nestedHref = nestedLink.getAttribute('href');
			var nestedTarget = nestedLink.getAttribute('target');
			var nestedText = normalizeText(nestedLink.textContent);

			if (nestedHref) {
				card.setAttribute('href', nestedHref);
			}

			if (nestedTarget) {
				card.setAttribute('target', nestedTarget);
			}

			if (nestedText) {
				textElement.textContent = nestedText;
			}
		}

		var finalText = normalizeText(textElement.textContent);

		if (finalText) {
			textElement.textContent = finalText;
			textElement.setAttribute('title', finalText);
			card.setAttribute('aria-label', finalText);
		}

		if (!card.getAttribute('href')) {
			card.setAttribute('href', '#');
		}
	});
})();;

