						currentCardHeight +
							'px',
						'important'
					);

					slide.style.setProperty(
						'margin',
						'0',
						'important'
					);

					slide.style.setProperty(
						'padding',
						'0',
						'important'
					);

					slide.style.setProperty(
						'overflow',
						'visible',
						'important'
					);

					var card = cards[index];

					if (!card) {
						return;
					}

					normalizeIntermediateWrappers(
						card,
						slide
					);

					card.style.setProperty(
						'display',
						'flex',
						'important'
					);

					card.style.setProperty(
						'flex',
						'0 0 100%',
						'important'
					);

					card.style.setProperty(
						'align-self',
						'stretch',
						'important'
					);

					card.style.setProperty(
						'width',
						'100%',
						'important'
					);

					card.style.setProperty(
						'min-width',
						'100%',
						'important'
					);

					card.style.setProperty(
						'max-width',
						'100%',
						'important'
					);

					card.style.setProperty(
						'height',
						'100%',
						'important'
					);

					card.style.setProperty(
						'min-height',
						'100%',
						'important'
					);

					card.style.setProperty(
						'max-height',
						'100%',
						'important'
					);

					card.style.setProperty(
						'margin',
						'0',
						'important'
					);

					card.style.setProperty(
						'padding',
						'0',
						'important'
					);

					card.style.setProperty(
						'overflow',
						'visible',
						'important'
					);

					card.setAttribute(
						'role',
						'group'
					);

					card.setAttribute(
						'aria-roledescription',
						'item'
					);

					card.setAttribute(
						'aria-label',
						'Card ' +
							(index + 1) +
							' de ' +
							cards.length
					);
				}
			);
		}

		function getStepSize() {
			return (
				currentCardWidth +
				currentGap
			);
		}

		function getMaximumOffset() {
			return Math.max(
				0,
				collectionTrack.scrollWidth -
					getViewportContentWidth()
			);
		}

		function getMaximumIndex() {
			var stepSize = getStepSize();

			var maximumOffset =
				getMaximumOffset();

			if (
				!stepSize ||
				maximumOffset <= 1
			) {
				return 0;
			}

			return Math.min(
				slides.length - 1,
				Math.ceil(
					maximumOffset /
						stepSize
				)
			);
		}

		function getOffsetByIndex(index) {
			return Math.min(
				index * getStepSize(),
				getMaximumOffset()
			);
		}

		function storeOriginalTabindex(
			element
		) {
			if (
				element.dataset
					.carouselOriginalTabindex !==
				undefined
			) {
				return;
			}

			element.dataset
				.carouselOriginalTabindex =
				element.hasAttribute(
					'tabindex'
				)
					? element.getAttribute(
							'tabindex'
						)
					: '';
		}

		function restoreOriginalTabindex(
			element
		) {
			if (
				element.dataset
					.carouselOriginalTabindex ===
				undefined
			) {
				return;
			}

			if (
				element.dataset
					.carouselOriginalTabindex === ''
			) {
				element.removeAttribute(
					'tabindex'
				);
			}
			else {
				element.setAttribute(
					'tabindex',
					element.dataset
						.carouselOriginalTabindex
				);
			}

			delete element.dataset
				.carouselOriginalTabindex;
		}

		function updateAccessibility() {
			var visibleStart =
				currentOffset;

			var visibleEnd =
				currentOffset +
				getViewportContentWidth();

			slides.forEach(
				function (slide, index) {
					var card = cards[index];

					if (!card) {
						return;
					}

					var slideStart =
						slide.offsetLeft;

					var slideEnd =
						slideStart +
						slide.offsetWidth;

					var overlap = Math.max(
						0,
						Math.min(
							slideEnd,
							visibleEnd
						) -
							Math.max(
								slideStart,
								visibleStart
							)
					);

					var minimumVisibleArea =
						Math.min(
							currentCardWidth,
							getViewportContentWidth()
						) * 0.45;

					var isVisible =
						overlap >=
						minimumVisibleArea;

					card.setAttribute(
						'aria-hidden',
						isVisible
							? 'false'
							: 'true'
					);

					var focusableElements =
						card.querySelectorAll(
							'a, button, input, select, textarea, [tabindex]'
						);

					Array.prototype.forEach.call(
						focusableElements,
						function (element) {
							if (isVisible) {
								restoreOriginalTabindex(
									element
								);
							}
							else {
								storeOriginalTabindex(
									element
								);

								element.setAttribute(
									'tabindex',
									'-1'
								);
							}
						}
					);
				}
			);
		}

		function updateControls() {
			var maximumIndex =
				getMaximumIndex();

			var hasNavigation =
				maximumIndex > 0;

			if (controls) {
				controls.hidden =
					!showNavigation ||
					!hasNavigation;
			}

			if (prevButton) {
				prevButton.disabled =
					!hasNavigation ||
					currentIndex <= 0;
			}

			if (nextButton) {
				nextButton.disabled =
					!hasNavigation ||
					currentIndex >=
						maximumIndex;
			}
		}

		function goToIndex(index, animate) {
			var maximumIndex =
				getMaximumIndex();

			currentIndex = Math.max(
				0,
				Math.min(
					index,
					maximumIndex
				)
			);

			currentOffset =
				getOffsetByIndex(
					currentIndex
				);

			collectionTrack.style.setProperty(
				'transition-duration',
				animate === false
					? '0ms'
					: transitionDuration +
						'ms',
				'important'
			);

			collectionTrack.style.setProperty(
				'transform',
				'translate3d(-' +
					currentOffset +
					'px, 0, 0)',
				'important'
			);

			updateControls();
			updateAccessibility();

			if (animate === false) {
				window.requestAnimationFrame(
					function () {
						collectionTrack.style
							.setProperty(
								'transition-duration',
								transitionDuration +
									'ms',
								'important'
							);
					}
				);
			}
		}

		function refreshOrder() {
			var refreshedCards = getCards();

			if (!refreshedCards.length) {
				return;
			}

			var refreshedEntries =
				createOrderedEntries(
					refreshedCards,
					collectionTrack
				);

			if (!refreshedEntries.length) {
				return;
			}

			var refreshedSignature =
				getOrderSignature(
					refreshedEntries
				);

			if (
				refreshedSignature ===
				lastOrderSignature
			) {
				return;
			}

			lastOrderSignature =
				refreshedSignature;

			stopAutoplay();

			refreshedEntries.forEach(
				function (entry) {
					collectionTrack.appendChild(
						entry.slide
					);
				}
			);

			hideEmptyTrackWrappers(
				collectionTrack,
				refreshedEntries.map(
					function (entry) {
						return entry.slide;
					}
				)
			);

			allCards = refreshedEntries.map(
				function (entry) {
					return entry.card;
				}
			);

			allSlides = refreshedEntries.map(
				function (entry) {
					return entry.slide;
				}
			);

			allSlides.forEach(
				function (slide, index) {
					slide.classList.add(
						'collection-card-carousel__slide'
					);

					if (index >= maximumCards) {
						slide.style.setProperty(
							'display',
							'none',
							'important'
						);
					}
					else {
						slide.style.setProperty(
							'display',
							'flex',
							'important'
						);
					}
				}
			);

			cards = allCards.slice(
				0,
				maximumCards
			);

			slides = allSlides.slice(
				0,
				maximumCards
			);

			if (cards.length) {
				referenceCard = cards[0];
			}

			currentIndex = 0;
			currentOffset = 0;

			applyLayout();
			goToIndex(0, false);
			startAutoplay();
		}

		function scheduleOrderRefresh() {
			clearTimeout(orderTimer);

			orderTimer = setTimeout(
				refreshOrder,
				80
			);
		}

		function nextItem() {
			goToIndex(
				currentIndex + 1,
				true
			);
		}

		function previousItem() {
			goToIndex(
				currentIndex - 1,
				true
			);
		}

		function stopAutoplay() {
			if (autoplayTimer) {
				clearInterval(
					autoplayTimer
				);

				autoplayTimer = null;
			}
		}

		function startAutoplay() {
			if (
				!autoplayEnabled ||
				document.hidden ||
				getMaximumIndex() < 1
			) {
				return;
			}

			stopAutoplay();

			autoplayTimer = setInterval(
				function () {
					if (
						currentIndex >=
						getMaximumIndex()
					) {
						goToIndex(0, true);
					}
					else {
						nextItem();
					}
				},
				autoplayDuration
			);
		}

		function resetAutoplay() {
			stopAutoplay();
			startAutoplay();
		}

		if (prevButton) {
			prevButton.addEventListener(
				'click',
				function () {
					previousItem();
					resetAutoplay();
				}
			);
		}

		if (nextButton) {
			nextButton.addEventListener(
				'click',
				function () {
					nextItem();
					resetAutoplay();
				}
			);
		}

		/* Swipe */

		var pointerStartX = 0;
		var pointerActive = false;
		var suppressClick = false;

		viewport.addEventListener(
			'pointerdown',
			function (event) {
				if (
					event.pointerType ===
						'mouse' &&
					event.button !== 0
				) {
					return;
				}

				pointerStartX =
					event.clientX;

				pointerActive = true;

				stopAutoplay();

				if (
					viewport.setPointerCapture
				) {
					viewport.setPointerCapture(
						event.pointerId
					);
				}
			}
		);

		viewport.addEventListener(
			'pointerup',
			function (event) {
				if (!pointerActive) {
					return;
				}

				var difference =
					event.clientX -
					pointerStartX;

				pointerActive = false;

				if (
					Math.abs(difference) >= 45
				) {
					suppressClick = true;

					if (difference < 0) {
						nextItem();
					}
					else {
						previousItem();
					}

					setTimeout(
						function () {
							suppressClick =
								false;
						},
						0
					);
				}

				startAutoplay();
			}
		);

		viewport.addEventListener(
			'pointercancel',
			function () {
				pointerActive = false;
				startAutoplay();
			}
		);

		viewport.addEventListener(
			'click',
			function (event) {
				if (!suppressClick) {
					return;
				}

				event.preventDefault();
				event.stopPropagation();
			},
			true
		);

		root.addEventListener(
			'mouseenter',
			stopAutoplay
		);

		root.addEventListener(
			'mouseleave',
			startAutoplay
		);

		root.addEventListener(
			'focusin',
			stopAutoplay
		);

		root.addEventListener(
			'focusout',
			function () {
				setTimeout(
					function () {
						if (
							!root.contains(
								document.activeElement
							)
						) {
							startAutoplay();
						}
					},
					0
				);
			}
		);

		root.addEventListener(
			'keydown',
			function (event) {
				if (
					getMaximumIndex() < 1
				) {
					return;
				}

				if (
					event.key ===
					'ArrowRight'
				) {
					event.preventDefault();

					nextItem();
					resetAutoplay();
				}

				if (
					event.key ===
					'ArrowLeft'
				) {
					event.preventDefault();

					previousItem();
					resetAutoplay();
				}
			}
		);

		document.addEventListener(
			'visibilitychange',
			function () {
				if (document.hidden) {
					stopAutoplay();
				}
				else {
					startAutoplay();
				}
			}
		);

		function handleResize() {
			clearTimeout(resizeTimer);

			resizeTimer = setTimeout(
				function () {
					applyLayout();

					goToIndex(
						Math.min(
							currentIndex,
							getMaximumIndex()
						),
						false
					);
				},
				120
			);
		}

		window.addEventListener(
			'resize',
			handleResize
		);

		if (
			typeof ResizeObserver ===
			'function'
		) {
			var resizeObserver =
				new ResizeObserver(
					handleResize
				);

			resizeObserver.observe(
				viewport
			);
		}

		if (typeof MutationObserver === 'function') {
			var orderObserver =
				new MutationObserver(
					scheduleOrderRefresh
				);

			orderObserver.observe(root, {
				childList: true,
				subtree: true,
				characterData: true
			});
		}

		setTimeout(scheduleOrderRefresh, 150);
		setTimeout(scheduleOrderRefresh, 400);
		setTimeout(scheduleOrderRefresh, 900);

		applyLayout();

		window.requestAnimationFrame(
			function () {
				goToIndex(0, false);
				startAutoplay();
			}
		);
	}

	if (!showNavigation && controls) {
		controls.hidden = true;
	}

	initializeCarousel();
})();;

