css:
.plan-card-item {
	position: relative;
	z-index: 1;

	display: flex;
	flex: 0 0 100%;
	align-self: stretch;

	width: 100%;
	min-width: 100%;
	max-width: 100%;

	height: 100%;
	min-height: 100%;
	max-height: 100%;

	margin: 0;
	padding: 0;

	overflow: visible;
	box-sizing: border-box;
}

.plan-card-item:hover,
.plan-card-item:focus-within {
	z-index: 20;
}

.plan-card {
	position: relative;
	isolation: isolate;

	display: flex;
	flex: 0 0 100%;
	flex-direction: column;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	height: 100%;
	min-height: 100%;
	max-height: 100%;

	margin: 2px;
	padding: 24px;

	overflow: hidden;

	color: #111111;
	background-color: #ffffff;

	border: 1px solid #d8dee7;
	border-radius: 8px;

	box-sizing: border-box;

	font-family: var(
		--font-family-figtree,
		Figtree,
		sans-serif
	);

	transition:
		box-shadow 200ms ease-in-out,
		border-color 200ms ease-in-out;
}

.plan-card:hover,
.plan-card:focus-within {
	border-color: transparent;

	box-shadow:
		0 0 0 1px #168bd2,
		0 10px 24px rgba(0, 20, 83, 0.16);
}

/* Dados auxiliares de mapeamento */

.plan-card__mapping-data {
	display: none;
}

.plan-card-item.plan-card-item--edit-mode
	.plan-card__mapping-data {
		position: absolute;
		right: 0;
		bottom: 0;
		z-index: 99;

		display: flex;
		flex-direction: column;
		gap: 4px;

		width: min(280px, calc(100% - 16px));
		max-height: 92px;
		padding: 6px;

		overflow: auto;

		background-color: #f3e8ff;
		border: 1px dashed #8b5cf6;
		border-radius: 4px;

		font-family: Arial, sans-serif;
		font-size: 10px;
		line-height: 14px;
}

.plan-card__mapping-field {
	display: flex;
	align-items: center;
	gap: 4px;

	min-width: 0;
}

.plan-card__mapping-label {
	flex: 0 0 auto;

	font-weight: 700;
	color: #5b21b6;
}

.plan-card__mapping-value {
	display: block;
	flex: 1 1 auto;

	min-width: 0;
	max-width: 100%;

	overflow: hidden;

	color: #4c1d95;

	text-overflow: ellipsis;
	white-space: nowrap;
}

/* Tag: uma linha */

.plan-card__tag {
	display: inline-flex;
	flex: 0 0 24px;
	align-items: center;
	align-self: flex-start;

	max-width: 100%;

	height: 24px;
	min-height: 24px;
	max-height: 24px;

	margin: 0 0 16px;
	padding: 2px 10px;

	overflow: hidden !important;

	color: #001453;
	background-color: #ffffff;

	border: 1px solid #001453;
	border-radius: 4px;

	font-family: inherit;
	font-size: 14px;
	font-style: normal;
	font-weight: 600;
	line-height: 18px;

	text-overflow: ellipsis;
	white-space: nowrap !important;
}

.plan-card__tag[hidden] {
	display: none !important;
}

/* Tag em destaque (controlada via campo booleano do objeto) */

.plan-card__tag--highlight {
	color: #ffffff;
	background-color: #001453;
	border-color: #001453;
}

/* Título: no máximo uma linha */

.plan-card__title {
	display: block;
	flex: 0 0 30px;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	height: 30px;
	min-height: 30px;
	max-height: 30px;

	margin: 0 0 4px;
	padding: 0;

	overflow: hidden !important;

	color: #111111;

	font-family: inherit;
	font-size: 28px;
	font-style: normal;
	font-weight: 600;
	line-height: 30px;

	text-overflow: ellipsis;
	white-space: nowrap !important;
}

/* Subtítulo: no máximo três linhas */

.plan-card__subtitle {
	display: -webkit-box;
	flex: 0 0 54px;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	height: 54px;
	min-height: 54px;
	max-height: 54px;

	margin: 0;
	padding: 0;

	overflow: hidden !important;

	color: #777777;

	font-family: inherit;
	font-size: 14px;
	font-style: normal;
	font-weight: 400;
	line-height: 18px;

	-webkit-box-orient: vertical;
	-webkit-line-clamp: 3;
	line-clamp: 3;

	overflow-wrap: anywhere;
	word-break: normal;
}

/*
 * Elementos que o editor/mapeamento do Liferay pode inserir.
 */

.plan-card__tag p,
.plan-card__tag div,
.plan-card__tag span,
.plan-card__title p,
.plan-card__title div,
.plan-card__title span {
	display: block !important;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	margin: 0 !important;
	padding: 0 !important;

	overflow: hidden !important;

	color: inherit !important;

	font-family: inherit !important;
	font-size: inherit !important;
	font-style: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;

	text-overflow: ellipsis !important;
	white-space: nowrap !important;
}

.plan-card__subtitle p,
.plan-card__subtitle div,
.plan-card__subtitle span {
	display: inline !important;

	margin: 0 !important;
	padding: 0 !important;

	color: inherit !important;

	font-family: inherit !important;
	font-size: inherit !important;
	font-style: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
}

/* Divisores */

.plan-card__divider {
	flex: 0 0 1px;

	width: 100%;

	height: 1px;
	min-height: 1px;
	max-height: 1px;

	margin: 16px 0;

	background-color: #e4e7eb;
}

.plan-card__divider[hidden] {
	display: none !important;
}

/*
 * Empurra o bloco final para baixo.
 * O divisor, o texto de cobertura e o botão
 * permanecem agrupados no fim do card.
 */

.plan-card__divider--footer {
	margin: auto 0 16px;
}

/* Tópicos */

.plan-card__topics {
	display: flex;
	flex: 0 0 auto;
	flex-direction: column;
	gap: 16px;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	margin: 0;
	padding: 0;

	overflow: hidden;
}

.plan-card__topic {
	display: flex;
	flex: 0 0 20px;
	align-items: center;
	gap: 10px;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	height: 20px;
	min-height: 20px;
	max-height: 20px;

	margin: 0;
	padding: 0;

	overflow: hidden !important;

	color: #333333;

	font-family: inherit;
	font-size: 14px;
	font-style: normal;
	font-weight: 400;
	line-height: 20px;
}

.plan-card__topic[hidden] {
	display: none !important;
}

.plan-card__topic-icon {
	position: relative;

	display: inline-flex;
	flex: 0 0 20px;
	align-items: center;
	justify-content: center;

	width: 20px;
	min-width: 20px;
	max-width: 20px;

	height: 20px;
	min-height: 20px;
	max-height: 20px;

	margin: 0;
	padding: 0;

	color: #001453;
	background-color: #eef3f8;

	border-radius: 50%;
}

.plan-card__topic-icon::before {
	content: "";

	width: 7px;
	height: 4px;

	border-bottom: 1.5px solid currentColor;
	border-left: 1.5px solid currentColor;

	transform: translateY(-1px) rotate(-45deg);
}

/* Texto do tópico: uma linha com reticências */

.plan-card__topic-text {
	display: block;
	flex: 1 1 auto;

	width: 0;
	min-width: 0;
	max-width: 100%;

	height: 20px;
	min-height: 20px;
	max-height: 20px;

	margin: 0;
	padding: 0;

	overflow: hidden !important;

	color: inherit;

	font-family: inherit;
	font-size: inherit;
	font-style: inherit;
	font-weight: inherit;
	line-height: inherit;

	text-overflow: ellipsis !important;
	white-space: nowrap !important;
}

.plan-card__topic-text p,
.plan-card__topic-text div,
.plan-card__topic-text span,
.plan-card__topic-text a {
	display: block !important;

	width: 100% !important;
	min-width: 0 !important;
	max-width: 100% !important;

	height: 20px !important;
	min-height: 20px !important;
	max-height: 20px !important;

	margin: 0 !important;
	padding: 0 !important;

	overflow: hidden !important;

	color: inherit !important;

	font-family: inherit !important;
	font-size: inherit !important;
	font-style: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;

	text-decoration: none !important;
	text-overflow: ellipsis !important;
	white-space: nowrap !important;
}

.plan-card__topic-divider {
	flex: 0 0 1px;

	width: 100%;

	height: 1px;
	min-height: 1px;
	max-height: 1px;

	margin: 1px 0;

	background-color: #e4e7eb;
}

.plan-card__topic-divider[hidden] {
	display: none !important;
}

/* Rodapé: no máximo três linhas */

.plan-card__footer-text {
	display: -webkit-box;
	flex: 0 0 36px;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	margin: 0 0 16px;
	padding: 0;

	overflow: hidden !important;

	color: #333333;

	font-family: inherit;
	font-size: 14px;
	font-style: normal;
	font-weight: 400;
	line-height: 18px;

	-webkit-box-orient: vertical;
	-webkit-line-clamp: 3;
	line-clamp: 3;

	overflow-wrap: anywhere;
	word-break: normal;
}

.plan-card__footer-text[hidden] {
	display: none !important;
}

/*
 * Caso não exista texto de cobertura,
 * mantém somente o botão no final do card.
 */

.plan-card__footer-text[hidden] + .plan-card__cta {
	margin-top: auto;
}

.plan-card__footer-text p,
.plan-card__footer-text div,
.plan-card__footer-text span {
	display: inline !important;

	margin: 0 !important;
	padding: 0 !important;

	color: inherit !important;

	font-family: inherit !important;
	font-size: inherit !important;
	font-style: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
}

/* CTA */

.plan-card__cta {
	display: inline-flex;
	flex: 0 0 44px;
	align-items: center;
	justify-content: center;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	height: 44px;
	min-height: 44px;
	max-height: 44px;

	margin: 0;
	padding: 0 20px;

	overflow: hidden;

	color: #001453;
	background-color: #87bcdc;

	border: 1px solid #87bcdc;
	border-radius: 6px;

	font-family: inherit;
	font-size: 16px;
	font-style: normal;
	font-weight: 600;
	line-height: 20px;

	text-align: center;
	text-decoration: none;

	box-sizing: border-box;

	transition:
		background-color 200ms ease-in-out,
		border-color 200ms ease-in-out,
		color 200ms ease-in-out;
}

.plan-card__cta:hover,
.plan-card__cta:focus {
	color: #ffffff;
	background-color: #001453;
	border-color: #001453;

	text-decoration: none;
}

.plan-card__cta:active {
	color: #ffffff;
	background-color: #344bb5;
	border-color: #344bb5;
}

.plan-card__cta:focus-visible {
	outline: 3px solid #168bd2;
	outline-offset: 3px;
}

.plan-card__cta-text {
	display: block;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	margin: 0;
	padding: 0;

	overflow: hidden !important;

	color: inherit;

	font-family: inherit;
	font-size: inherit;
	font-style: inherit;
	font-weight: inherit;
	line-height: inherit;

	text-overflow: ellipsis !important;
	white-space: nowrap !important;
}

.plan-card__cta-text p,
.plan-card__cta-text div,
.plan-card__cta-text span,
.plan-card__cta-text a {
	display: block !important;

	width: 100%;
	min-width: 0;
	max-width: 100%;

	margin: 0 !important;
	padding: 0 !important;

	overflow: hidden !important;

	color: inherit !important;

	font-family: inherit !important;
	font-size: inherit !important;
	font-style: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;

	text-decoration: none !important;
	text-overflow: ellipsis !important;
	white-space: nowrap !important;
}

/* Tablet */

@media (min-width: 481px) and (max-width: 1024px) {
	.plan-card {
		padding: 24px;
	}

	.plan-card__title {
		font-size: 20px;
	}

	.plan-card__footer-text {
		flex: 0 0 54px;
	}
}

/* Mobile */

@media (max-width: 480px) {
	.plan-card {
		padding: 24px 20px;
	}

	.plan-card__title {
		font-size: 20px;
		line-height: 30px;
	}

	.plan-card__footer-text {
		flex: 0 0 54px;
	}
}

/* Redução de movimento */

@media (prefers-reduced-motion: reduce) {
	.plan-card {
		transition: none;
	}
}

/*
 * Proteção do CTA contra sobreposição
 * e captura de eventos pelo carrossel.
 */

.plan-card__cta {
	position: relative;
	z-index: 50;

	pointer-events: auto !important;
	touch-action: manipulation;

	cursor: pointer;

	-webkit-user-drag: none;
	user-select: none;
	-webkit-user-select: none;
}

/*
 * Fora do editor, o conteúdo interno
 * não captura o clique.
 */

.plan-card-item:not(.plan-card-item--edit-mode)
	.plan-card__cta > * {
	pointer-events: none;
}

/*
 * No editor do Liferay,
 * o conteúdo continua editável.
 */

.plan-card-item.plan-card-item--edit-mode
	.plan-card__cta,
.plan-card-item.plan-card-item--edit-mode
	.plan-card__cta > * {
	pointer-events: auto;
}

/*
 * Mantém o card acima dos elementos vizinhos
 * durante hover ou navegação por teclado.
 */

.plan-card-item:hover,
.plan-card-item:focus-within {
	z-index: 50;
}

