(function () {
	var root = fragmentElement.querySelector(
		'.plan-card-item'
	);

	if (!root) {
		return;
	}

	if (root.dataset.planCardInitialized === 'true') {
		return;
	}

	root.dataset.planCardInitialized = 'true';

	var card = root.querySelector('.plan-card');

	if (!card) {
		return;
	}

	var orderField = root.querySelector(
		'.js-card-order'
	);

	var separateBenefitsField = root.querySelector(
		'.js-separate-benefits'
	);

	var ctaUrlField = root.querySelector(
		'.js-cta-url'
	);

	var tagHighlightField = root.querySelector(
		'.js-tag-highlight'
	);

	var tag = root.querySelector(
		'.plan-card__tag'
	);

	var topics = Array.prototype.slice.call(
		root.querySelectorAll('.plan-card__topic')
	);

	var topicDivider = root.querySelector(
		'.plan-card__topic-divider'
	);

	var footerText = root.querySelector(
		'.plan-card__footer-text'
	);

	var footerDivider = root.querySelector(
		'.plan-card__divider--footer'
	);

	var cta = root.querySelector(
		'.plan-card__cta'
	);

	var ctaText = root.querySelector(
		'.plan-card__cta-text'
	);

	var defaultCtaUrl =
		'https://contrate-online.gndi.com.br';

	var updateTimer = null;

	/*
	 * Controle utilizado para distinguir um clique
	 * de um movimento de arraste.
	 */
	var pointerState = {
		active: false,
		moved: false,
		startX: 0,
		startY: 0,
		pointerId: null,
		ignoreClickUntil: 0
	};

	function isEditMode() {
		return (
			document.body.classList.contains(
				'has-edit-mode-menu'
			) ||
			document.documentElement.classList.contains(
				'has-edit-mode-menu'
			) ||
			!!document.querySelector(
				'.page-editor__sidebar'
			) ||
			!!document.querySelector(
				'.page-editor__topper'
			) ||
			!!document.querySelector(
				'.page-editor__toolbar'
			) ||
			!!document.querySelector(
				'.page-editor__page-structure'
			)
		);
	}

	function normalizeText(value) {
		return String(value || '')
			.replace(
				/[\u200B\u200C\u200D\uFEFF]/g,
				''
			)
			.replace(/\u00A0/g, ' ')
			.replace(/\s+/g, ' ')
			.trim();
	}

	function normalizeComparableValue(value) {
		return normalizeText(value)
			.toLowerCase()
			.normalize('NFD')
			.replace(/[\u0300-\u036f]/g, '');
	}

	function getElementText(element) {
		if (!element) {
			return '';
		}

		return normalizeText(element.textContent);
	}

	function hasMeaningfulText(element) {
		var value = normalizeComparableValue(
			getElementText(element)
		);

		return (
			value !== '' &&
			value !== 'null' &&
			value !== 'undefined' &&
			value !== 'n/a' &&
			value !== '-'
		);
	}

	function parseBoolean(value) {
		var normalizedValue =
			normalizeComparableValue(value);

		return (
			normalizedValue === 'true' ||
			normalizedValue === '1' ||
			normalizedValue === 'sim' ||
			normalizedValue === 'yes' ||
			normalizedValue === 'on' ||
			normalizedValue === 'com secoes' ||
			normalizedValue === 'com secao' ||
			normalizedValue === 'separado' ||
			normalizedValue === 'separar'
		);
	}

	function parseOrder(value) {
		var normalizedValue = normalizeText(value)
			.replace(',', '.');

		var parsedValue = parseFloat(normalizedValue);

		return isNaN(parsedValue)
			? ''
			: String(parsedValue);
	}

	function getTopicTextElement(topic) {
		if (!topic) {
			return null;
		}

		return topic.querySelector(
			'.plan-card__topic-text'
		);
	}

	function hasTopicContent(topic) {
		return hasMeaningfulText(
			getTopicTextElement(topic)
		);
	}

	function getMappedUrl(element) {
		if (!element) {
			return '';
		}

		var mappedAnchor =
			element.querySelector('a[href]');

		if (mappedAnchor) {
			return normalizeText(
				mappedAnchor.getAttribute('href')
			);
		}

		return getElementText(element);
	}

	function getSafeUrl(value) {
		var normalizedValue = normalizeText(value);

		if (!normalizedValue) {
			return defaultCtaUrl;
		}

		try {
			var parsedUrl = new URL(
				normalizedValue,
				window.location.origin
			);

			if (
				parsedUrl.protocol !== 'http:' &&
				parsedUrl.protocol !== 'https:'
			) {
				return defaultCtaUrl;
			}

			return parsedUrl.href;
		}
		catch (error) {
			return defaultCtaUrl;
		}
	}

	function hasNavigationModifier(event) {
		return (
			event.ctrlKey ||
			event.metaKey ||
			event.shiftKey ||
			event.altKey
		);
	}

	function getCtaUrl() {
		if (!cta) {
			return '';
		}

		return getSafeUrl(
			cta.getAttribute('href')
		);
	}

	function openCtaUrl(event) {
		if (!cta || isEditMode()) {
			return;
		}

		var href = getCtaUrl();

		if (!href) {
			return;
		}

		var target = cta.getAttribute('target');

		var shouldOpenNewWindow =
			target === '_blank' ||
			(event && hasNavigationModifier(event));

		if (shouldOpenNewWindow) {
			var openedWindow = window.open(
				href,
				'_blank',
				'noopener,noreferrer'
			);

			if (openedWindow) {
				openedWindow.opener = null;
			}

			return;
		}

		window.location.assign(href);
	}

	function resetPointerState() {
		pointerState.active = false;
		pointerState.moved = false;
		pointerState.pointerId = null;
	}

	function bindCtaInteraction() {
		if (!cta) {
			return;
		}

		if (
			cta.dataset.planCardCtaInitialized ===
			'true'
		) {
			return;
		}

		cta.dataset.planCardCtaInitialized = 'true';

		cta.setAttribute('draggable', 'false');
		cta.setAttribute(
			'data-senna-off',
			'true'
		);

		/*
		 * Impede que o inÃ­cio do clique seja tratado
		 * pelo carrossel como arraste.
		 */
		cta.addEventListener(
			'pointerdown',
			function (event) {
				if (isEditMode()) {
					return;
				}

				if (
					typeof event.button === 'number' &&
					event.button !== 0
				) {
					return;
				}

				pointerState.active = true;
				pointerState.moved = false;
				pointerState.startX = event.clientX;
				pointerState.startY = event.clientY;
				pointerState.pointerId =
					event.pointerId;

				event.stopPropagation();
			}
		);

		cta.addEventListener(
			'pointermove',
			function (event) {
				if (!pointerState.active) {
					return;
				}

				if (
					pointerState.pointerId !== null &&
					event.pointerId !==
						pointerState.pointerId
				) {
					return;
				}

				var distanceX = Math.abs(
					event.clientX -
						pointerState.startX
				);

				var distanceY = Math.abs(
					event.clientY -
						pointerState.startY
				);

				if (
					distanceX > 8 ||
					distanceY > 8
				) {
					pointerState.moved = true;
				}

				event.stopPropagation();
			}
		);

		cta.addEventListener(
			'pointerup',
			function (event) {
				if (!pointerState.active) {
					return;
				}

				if (
					pointerState.pointerId !== null &&
					event.pointerId !==
						pointerState.pointerId
				) {
					return;
				}

				var shouldNavigate =
					!pointerState.moved &&
					!isEditMode() &&
					!hasNavigationModifier(event);

				resetPointerState();

				event.stopPropagation();

				if (!shouldNavigate) {
					return;
				}

				/*
				 * A navegaÃ§ÃĢo acontece no pointerup para
				 * evitar que o pai cancele o evento click.
				 */
				event.preventDefault();

				pointerState.ignoreClickUntil =
					Date.now() + 500;

				openCtaUrl(event);
			}
		);

		cta.addEventListener(
			'pointercancel',
			function (event) {
				resetPointerState();
				event.stopPropagation();
			}
		);

		/*
		 * Fallback para navegadores ou scripts que
		 * ainda utilizam eventos de mouse.
		 */
		cta.addEventListener(
			'mousedown',
			function (event) {
				if (!isEditMode()) {
					event.stopPropagation();
				}
			}
		);

		cta.addEventListener(
			'mouseup',
			function (event) {
				if (!isEditMode()) {
					event.stopPropagation();
				}
			}
		);

		cta.addEventListener(
			'dragstart',
			function (event) {
				event.preventDefault();
				event.stopPropagation();
			}
		);

		/*
		 * MantÃĐm o funcionamento por teclado e atua
		 * como fallback caso o pointerup nÃĢo seja usado.
		 */
		cta.addEventListener(
			'click',
			function (event) {
				event.stopPropagation();

				if (isEditMode()) {
					event.preventDefault();
					return;
				}

				if (
					Date.now() <
					pointerState.ignoreClickUntil
				) {
					event.preventDefault();
					return;
				}

				/*
				 * Ctrl, Command e Shift continuam usando
				 * o comportamento nativo do navegador.
				 */
				if (hasNavigationModifier(event)) {
					return;
				}

				event.preventDefault();
				openCtaUrl(event);
			}
		);

		/*
		 * Enter e barra de espaÃ§o para acessibilidade.
		 * O Enter normalmente dispara click; o Space
		 * ÃĐ tratado manualmente.
		 */
		cta.addEventListener(
			'keydown',
			function (event) {
				if (isEditMode()) {
					return;
				}

				if (
					event.key === ' ' ||
					event.key === 'Spacebar'
				) {
					event.preventDefault();
					event.stopPropagation();
					openCtaUrl(event);
				}
			}
		);
	}

	function applyCardRules() {
		var editing = isEditMode();

		root.classList.toggle(
			'plan-card-item--edit-mode',
			editing
		);

		var normalizedOrder = parseOrder(
			getElementText(orderField)
		);

		if (normalizedOrder) {
			root.dataset.carouselOrder =
				normalizedOrder;
		}
		else {
			delete root.dataset.carouselOrder;
		}

		var separateBenefits = parseBoolean(
			getElementText(separateBenefitsField)
		);

		card.classList.toggle(
			'plan-card--sectioned',
			separateBenefits
		);

		card.classList.toggle(
			'plan-card--single-section',
			!separateBenefits
		);

		if (tag) {
			tag.hidden =
				!editing &&
				!hasMeaningfulText(tag);

			var isTagHighlighted = parseBoolean(
				getElementText(tagHighlightField)
			);

			tag.classList.toggle(
				'plan-card__tag--highlight',
				isTagHighlighted
			);
		}

		var topicLimit = separateBenefits ? 6 : 8;

		topics.forEach(function (topic, index) {
			var hasContent =
				hasTopicContent(topic);

			var exceedsLimit = index >= topicLimit;

			if (editing) {
				topic.hidden = false;

				topic.classList.toggle(
					'is-empty',
					!hasContent
				);

				return;
			}

			topic.hidden =
				!hasContent || exceedsLimit;

			topic.classList.toggle(
				'is-empty',
				!hasContent
			);
		});

		var firstSectionHasContent = topics
			.slice(0, 3)
			.some(function (topic) {
				return (
					topic &&
					!topic.hidden &&
					hasTopicContent(topic)
				);
			});

		var secondSectionHasContent = topics
			.slice(3, 6)
			.some(function (topic) {
				return (
					topic &&
					!topic.hidden &&
					hasTopicContent(topic)
				);
			});

		if (topicDivider) {
			topicDivider.hidden =
				!separateBenefits ||
				!firstSectionHasContent ||
				!secondSectionHasContent;
		}

		var hasFooterText =
			hasMeaningfulText(footerText);

		if (footerText) {
			footerText.hidden =
				!editing && !hasFooterText;
		}

		if (footerDivider) {
			footerDivider.hidden =
				!editing && !hasFooterText;
		}

		if (
			ctaText &&
			!hasMeaningfulText(ctaText)
		) {
			ctaText.textContent =
				'Solicitar proposta';
		}

		if (cta) {
			var mappedUrl =
				getMappedUrl(ctaUrlField);

			var safeUrl =
				getSafeUrl(mappedUrl);

			cta.setAttribute('href', safeUrl);

			cta.setAttribute(
				'aria-label',
				getElementText(ctaText) ||
					'Solicitar proposta'
			);

			cta.setAttribute(
				'draggable',
				'false'
			);

			cta.setAttribute(
				'data-senna-off',
				'true'
			);
		}
	}

	function scheduleUpdate() {
		clearTimeout(updateTimer);

		updateTimer = setTimeout(
			applyCardRules,
			60
		);
	}

	bindCtaInteraction();
	applyCardRules();

	setTimeout(applyCardRules, 150);
	setTimeout(applyCardRules, 400);
	setTimeout(applyCardRules, 900);

	if (typeof MutationObserver === 'function') {
		var observer = new MutationObserver(
			scheduleUpdate
		);

		observer.observe(root, {
			childList: true,
			subtree: true,
			characterData: true
		});
	}

	root.addEventListener(
		'input',
		scheduleUpdate,
		true
	);

	root.addEventListener(
		'change',
		scheduleUpdate,
		true
	);

	root.addEventListener(
		'blur',
		scheduleUpdate,
		true
	);
})();;

css:
.collection-card-carousel {
	--carousel-container-width: 1440px;
	--carousel-card-width: 419px;
	--carousel-card-height: 388px;
	--carousel-gap: 24px;
	--carousel-edge-inset: 0px;
	--carousel-transition-duration: 400ms;
	--carousel-safe-x: 0px;
	--carousel-safe-top: 0px;
	--carousel-safe-bottom: 0px;

	position: relative;
	width: 100%;
	max-width: calc(
		var(--carousel-container-width) +
		(var(--carousel-safe-x) * 2)
	);
	margin: 0;
	overflow: visible;
	font-family: var(
		--font-family-figtree,
		Figtree,
		sans-serif
	);
}

.collection-card-carousel,
.collection-card-carousel * {
	box-sizing: border-box;
}

.collection-card-carousel__viewport {
	position: relative;
	width: 100%;
	margin: 0;
	overflow: hidden;
	touch-action: pan-y;
}

.collection-card-carousel__track {
	position: relative;
	display: block;
	width: 100%;
	margin: 0;
	padding: 0;
	overflow: visible;
}

.collection-card-carousel__collection-track {
	display: flex !important;
	flex-direction: row !important;
	flex-wrap: nowrap !important;
	align-items: stretch !important;
	justify-content: flex-start !important;
	gap: var(--carousel-gap) !important;
	width: max-content !important;
	min-width: 100% !important;
	margin: 1px !important;
	padding-top: 0 !important;
	padding-right: var(--carousel-edge-inset) !important;
	padding-bottom: 0 !important;
	padding-left: var(--carousel-edge-inset) !important;
	overflow: visible !important;
	transform: translate3d(0, 0, 0);
	transition:
		transform
		var(--carousel-transition-duration)
		ease-out;
	will-change: transform;
}

.collection-card-carousel__slide {
	position: relative;
	z-index: 1;
	display: flex !important;
	flex: 0 0 var(--carousel-card-width) !important;
	align-self: stretch !important;
	width: var(--carousel-card-width) !important;
	min-width: var(--carousel-card-width) !important;
	max-width: var(--carousel-card-width) !important;
	height: var(--carousel-card-height) !important;
	min-height: var(--carousel-card-height) !important;
	max-height: var(--carousel-card-height) !important;
	margin: 0 !important;
	padding: 0 !important;
	overflow: visible !important;
	box-sizing: border-box !important;
}

.collection-card-carousel__slide:hover,
.collection-card-carousel__slide:focus-within {
	z-index: 30;
}

/*
 * Fragmento filho.
 * O slide controla a largura em pixels; o filho deve preencher 100% do slide.
 */
.collection-card-carousel__slide
	.collection-card-carousel__item {
	position: relative;
	display: flex !important;
	flex: 0 0 100% !important;
	align-self: stretch !important;
	width: 100% !important;
	min-width: 100% !important;
	max-width: 100% !important;
	height: 100% !important;
	min-height: 100% !important;
	max-height: 100% !important;
	margin: 0 !important;
	padding: 0 !important;
	overflow: visible !important;
	box-sizing: border-box !important;
}

/*
 * Wrappers comuns que o Liferay pode inserir entre o slide e o fragmento.
 * O JavaScript também normaliza qualquer wrapper não previsto aqui.
 */
.collection-card-carousel__slide
	.lfr-layout-structure-item-container,
.collection-card-carousel__slide
	.lfr-layout-structure-item-collection,
.collection-card-carousel__slide
	.lfr-layout-structure-item-row,
.collection-card-carousel__slide
	.lfr-layout-structure-item-com.liferay-drop-zone,
.collection-card-carousel__slide
	.fragment-entry-link,
.collection-card-carousel__slide
	.fragment-entry-link-wrapper,
.collection-card-carousel__slide
	.portlet,
.collection-card-carousel__slide
	.portlet-content,
.collection-card-carousel__slide
	.portlet-content-container {
	flex: 0 0 100% !important;
	align-self: stretch !important;
	width: 100% !important;
	min-width: 100% !important;
	max-width: 100% !important;
	height: 100% !important;
	min-height: 100% !important;
	max-height: 100% !important;
	margin: 0 !important;
	padding: 0 !important;
	box-sizing: border-box !important;
}

.collection-card-carousel__slide
	.collection-card-carousel__item:hover,
.collection-card-carousel__slide
	.collection-card-carousel__item:focus-within {
	z-index: 40;
}

/* Controles */

.collection-card-carousel__controls {
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 12px;
	width: 100%;
	margin: 30px 0 0;
	padding-inline: var(--carousel-safe-x);
}

.collection-card-carousel__controls[hidden] {
	display: none !important;
}

.collection-card-carousel__arrow {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 32px;
	height: 32px;
	min-width: 32px;
	min-height: 32px;
	margin: 0;
	padding: 0;
	color: #ffffff;
	border: 1px solid transparent;
	border-radius: 4px;
	cursor: pointer;
	transition:
		background-color 200ms ease-out,
		border-color 200ms ease-out,
		color 200ms ease-out,
		opacity 200ms ease-out;
}

.collection-card-carousel__arrow svg {
	display: block;
	width: 8px;
	height: 14px;
	pointer-events: none;
}

/*
 * Estado ativo das duas setas.
 * A aparência depende apenas do atributo disabled,
 * não da direção da seta.
 */
.collection-card-carousel__arrow:not(:disabled) {
	color: #ffffff;
	background-color: #12263f;
	border-color: #12263f;
}

.collection-card-carousel__arrow:not(:disabled):hover,
.collection-card-carousel__arrow:not(:disabled):focus {
	color: #ffffff;
	background-color: #061b49;
	border-color: #061b49;
}

.collection-card-carousel__arrow:not(:disabled):active {
	color: #ffffff;
	background-color: #344bb5;
	border-color: #344bb5;
}

.collection-card-carousel__arrow:focus-visible {
	outline: 2px solid #061b49;
	outline-offset: 3px;
}

.collection-card-carousel__arrow:disabled {
	color: #ffffff;
	background-color: #dce3eb;
	border-color: #dce3eb;
	cursor: not-allowed;
	opacity: 1;
}

.collection-card-carousel[data-show-navigation="false"]
	.collection-card-carousel__controls {
	display: none !important;
}

/* Modo de edição do Liferay */

.collection-card-carousel.collection-card-carousel--edit-mode {
	max-width: 100%;
	overflow: visible;
}

.collection-card-carousel.collection-card-carousel--edit-mode
	.collection-card-carousel__viewport {
	width: 100%;
	margin: 0;
	padding: 0;
	overflow: visible;
}

.collection-card-carousel.collection-card-carousel--edit-mode
	.collection-card-carousel__track {
	display: block;
	width: 100%;
	transform: none !important;
	transition: none !important;
}

/*
 * No editor, o Collection Display pode criar wrappers
 * agrupando mais de um item. Eles não podem encolher,
 * senão os cards ficam comprimidos quando há 4 ou mais.
 */
.collection-card-carousel.collection-card-carousel--edit-mode
	.collection-card-carousel__collection-track > * {
	flex: 0 0 auto !important;
	width: max-content !important;
	min-width: max-content !important;
	max-width: none !important;
}

.collection-card-carousel.collection-card-carousel--edit-mode
	.collection-card-carousel__controls {
	display: none !important;
}

/* Tablet */

@media (min-width: 768px) and (max-width: 1024px) {
	.collection-card-carousel {
		--carousel-safe-top: 18px;
		--carousel-safe-bottom: 28px;
	}
}

/* Mobile */

@media (max-width: 767px) {
	.collection-card-carousel {
		--carousel-safe-x: 6px;
		--carousel-safe-top: 18px;
		--carousel-safe-bottom: 28px;
	}

	.collection-card-carousel__controls {
		gap: 10px;
	}
}

/* Redução de movimento */

@media (prefers-reduced-motion: reduce) {
	.collection-card-carousel__collection-track {
		transition: none !important;
	}
}

js:
(function () {
	var root = fragmentElement.querySelector(
		'.collection-card-carousel'
	);

	if (!root) {
		return;
	}

	if (
		root.dataset.collectionCarouselInitialized ===
		'true'
	) {
		return;
	}

	root.dataset.collectionCarouselInitialized =
		'true';

	var viewport = root.querySelector(
		'.collection-card-carousel__viewport'
	);

	var outerTrack = root.querySelector(
		'.collection-card-carousel__track'
	);

	var controls = root.querySelector(
		'.collection-card-carousel__controls'
	);

	var prevButton = root.querySelector(
		'.collection-card-carousel__arrow--prev'
	);

	var nextButton = root.querySelector(
		'.collection-card-carousel__arrow--next'
	);

	if (!viewport || !outerTrack) {
		return;
	}

	var attempts = 0;
	var maximumAttempts = 50;
	var maximumCards = 9;

	var showNavigation =
		root.getAttribute(
			'data-show-navigation'
		) !== 'false';

	function isEditMode() {
		return (
			document.body.classList.contains(
				'has-edit-mode-menu'
			) ||
			document.documentElement.classList.contains(
				'has-edit-mode-menu'
			) ||
			!!document.querySelector(
				'.page-editor__sidebar'
			) ||
			!!document.querySelector(
				'.page-editor__topper'
			) ||
			!!document.querySelector(
				'.page-editor__toolbar'
			) ||
			!!document.querySelector(
				'.page-editor__page-structure'
			)
		);
	}

	function getCards() {
		return Array.prototype.slice
			.call(
				root.querySelectorAll(
					'.collection-card-carousel__item'
				)
			)
			.filter(function (card) {
				return (
					card.closest(
						'.collection-card-carousel'
					) === root
				);
			});
	}

	function containsAllCards(element, cards) {
		var index;

		if (!element) {
			return false;
		}

		for (
			index = 0;
			index < cards.length;
			index++
		) {
			if (!element.contains(cards[index])) {
				return false;
			}
		}

		return true;
	}

	function findCollectionTrack(cards) {
		if (!cards.length) {
			return null;
		}

		var ancestor = cards[0].parentElement;

		while (
			ancestor &&
			ancestor !== outerTrack &&
			!containsAllCards(ancestor, cards)
		) {
			ancestor = ancestor.parentElement;
		}

		if (
			ancestor &&
			containsAllCards(ancestor, cards)
		) {
			return ancestor;
		}

		return outerTrack;
	}

	function countCardsInside(element, cards) {
		var count = 0;

		if (!element) {
			return count;
		}

		cards.forEach(function (card) {
			if (element.contains(card)) {
				count++;
			}
		});

		return count;
	}

	/*
	 * Retorna o wrapper mais externo que ainda pertence
	 * exclusivamente a um único card.
	 *
	 * Isso evita que wrappers do Collection Display que
	 * agrupam dois ou mais itens sejam tratados como um
	 * único slide, fazendo cards desaparecerem.
	 */
	function getDirectSlide(
		card,
		collectionTrack,
		cards
	) {
		var element = card;
		var slide = card;

		while (
			element.parentElement &&
			element.parentElement !==
				collectionTrack
		) {
			var parent = element.parentElement;

			if (
				countCardsInside(parent, cards) > 1
			) {
				break;
			}

			slide = parent;
			element = parent;
		}

		return slide;
	}

	function getSlides(
		cards,
		collectionTrack
	) {
		return cards.map(function (card) {
			return getDirectSlide(
				card,
				collectionTrack,
				cards
			);
		});
	}

	var carouselRuntimeCardId = 0;

	function normalizeOrderValue(value) {
		return String(value || '')
			.replace(/[\u200B\u200C\u200D\uFEFF]/g, '')
			.replace(/\u00A0/g, ' ')
			.replace(/\s+/g, ' ')
			.trim();
	}

	function getCardRuntimeId(card) {
		if (!card.dataset.carouselRuntimeId) {
			carouselRuntimeCardId++;

			card.dataset.carouselRuntimeId =
				'carousel-card-' +
				carouselRuntimeCardId;
		}

		return card.dataset.carouselRuntimeId;
	}

	function getCardOrder(card) {
		if (!card) {
			return {
				hasOrder: false,
				value: Number.POSITIVE_INFINITY,
				raw: ''
			};
		}

		var selector =
			card.getAttribute(
				'data-carousel-order-selector'
			) || '.js-card-order';

		var orderSource = null;

		try {
			orderSource = card.querySelector(selector);
		}
		catch (error) {
