		function getMaximumOffset() {
			return Math.max(
				0,
				collectionTrack.scrollWidth -
					getViewportContentWidth()
			);
		}

		function getMaximumIndex() {
			var stepSize = getStepSize();

			var maximumOffset =
				getMaximumOffset();

			if (
				!stepSize ||
				maximumOffset <= 1
			) {
				return 0;
			}

			return Math.min(
				slides.length - 1,
				Math.ceil(
					maximumOffset /
						stepSize
				)
			);
		}

		function getOffsetByIndex(index) {
			return Math.min(
				index * getStepSize(),
				getMaximumOffset()
			);
		}

		function storeOriginalTabindex(
			element
		) {
			if (
				element.dataset
					.carouselOriginalTabindex !==
				undefined
			) {
				return;
			}

			element.dataset
				.carouselOriginalTabindex =
				element.hasAttribute(
					'tabindex'
				)
					? element.getAttribute(
							'tabindex'
						)
					: '';
		}

		function restoreOriginalTabindex(
			element
		) {
			if (
				element.dataset
					.carouselOriginalTabindex ===
				undefined
			) {
				return;
			}

			if (
				element.dataset
					.carouselOriginalTabindex === ''
			) {
				element.removeAttribute(
					'tabindex'
				);
			}
			else {
				element.setAttribute(
					'tabindex',
					element.dataset
						.carouselOriginalTabindex
				);
			}

			delete element.dataset
				.carouselOriginalTabindex;
		}

		function updateAccessibility() {
			var visibleStart =
				currentOffset;

			var visibleEnd =
				currentOffset +
				getViewportContentWidth();

			slides.forEach(
				function (slide, index) {
					var card = cards[index];

					if (!card) {
						return;
					}

					var slideStart =
						slide.offsetLeft;

					var slideEnd =
						slideStart +
						slide.offsetWidth;

					var overlap = Math.max(
						0,
						Math.min(
							slideEnd,
							visibleEnd
						) -
							Math.max(
								slideStart,
								visibleStart
							)
					);

					var minimumVisibleArea =
						Math.min(
							currentCardWidth,
							getViewportContentWidth()
						) * 0.45;

					var isVisible =
						overlap >=
						minimumVisibleArea;

					card.setAttribute(
						'aria-hidden',
						isVisible
							? 'false'
							: 'true'
					);

					var focusableElements =
						card.querySelectorAll(
							'a, button, input, select, textarea, [tabindex]'
						);

					Array.prototype.forEach.call(
						focusableElements,
						function (element) {
							if (isVisible) {
								restoreOriginalTabindex(
									element
								);
							}
							else {
								storeOriginalTabindex(
									element
								);

								element.setAttribute(
									'tabindex',
									'-1'
								);
							}
						}
					);
				}
			);
		}

		function updateControls() {
			var maximumIndex =
				getMaximumIndex();

			var hasNavigation =
				maximumIndex > 0;

			if (controls) {
				controls.hidden =
					!showNavigation ||
					!hasNavigation;
			}

			if (prevButton) {
				prevButton.disabled =
					!hasNavigation ||
					currentIndex <= 0;
			}

			if (nextButton) {
				nextButton.disabled =
					!hasNavigation ||
					currentIndex >=
						maximumIndex;
			}
		}

		function goToIndex(index, animate) {
			var maximumIndex =
				getMaximumIndex();

			currentIndex = Math.max(
				0,
				Math.min(
					index,
					maximumIndex
				)
			);

			currentOffset =
				getOffsetByIndex(
					currentIndex
				);

			collectionTrack.style.setProperty(
				'transition-duration',
				animate === false
					? '0ms'
					: transitionDuration +
						'ms',
				'important'
			);

			collectionTrack.style.setProperty(
				'transform',
				'translate3d(-' +
					currentOffset +
					'px, 0, 0)',
				'important'
			);

			updateControls();
			updateAccessibility();

			if (animate === false) {
				window.requestAnimationFrame(
					function () {
						collectionTrack.style
							.setProperty(
								'transition-duration',
								transitionDuration +
									'ms',
								'important'
							);
					}
				);
			}
		}

		function refreshOrder() {
			var refreshedCards = getCards();

			if (!refreshedCards.length) {
				return;
			}

			var refreshedEntries =
				createOrderedEntries(
					refreshedCards,
					collectionTrack
				);

			if (!refreshedEntries.length) {
				return;
			}

			var refreshedSignature =
				getOrderSignature(
					refreshedEntries
				);

			if (
				refreshedSignature ===
				lastOrderSignature
			) {
				return;
			}

			lastOrderSignature =
				refreshedSignature;

			stopAutoplay();

			refreshedEntries.forEach(
				function (entry) {
					collectionTrack.appendChild(
						entry.slide
					);
				}
			);

			hideEmptyTrackWrappers(
				collectionTrack,
				refreshedEntries.map(
					function (entry) {
						return entry.slide;
					}
				)
			);

			allCards = refreshedEntries.map(
				function (entry) {
					return entry.card;
				}
			);

			allSlides = refreshedEntries.map(
				function (entry) {
					return entry.slide;
				}
			);

			allSlides.forEach(
				function (slide, index) {
					slide.classList.add(
						'collection-card-carousel__slide'
					);

					if (index >= maximumCards) {
						slide.style.setProperty(
							'display',
							'none',
							'important'
						);
					}
					else {
						slide.style.setProperty(
							'display',
							'flex',
							'important'
						);
					}
				}
			);

			cards = allCards.slice(
				0,
				maximumCards
			);

			slides = allSlides.slice(
				0,
				maximumCards
			);

			if (cards.length) {
				referenceCard = cards[0];
			}

			currentIndex = 0;
			currentOffset = 0;

			applyLayout();
			goToIndex(0, false);
			startAutoplay();
		}

		function scheduleOrderRefresh() {
			clearTimeout(orderTimer);

			orderTimer = setTimeout(
				refreshOrder,
				80
			);
		}

		function nextItem() {
			goToIndex(
				currentIndex + 1,
				true
			);
		}

		function previousItem() {
			goToIndex(
				currentIndex - 1,
				true
			);
		}

		function stopAutoplay() {
			if (autoplayTimer) {
				clearInterval(
					autoplayTimer
				);

				autoplayTimer = null;
			}
		}

		function startAutoplay() {
			if (
				!autoplayEnabled ||
				document.hidden ||
				getMaximumIndex() < 1
			) {
				return;
			}

			stopAutoplay();

			autoplayTimer = setInterval(
				function () {
					if (
						currentIndex >=
						getMaximumIndex()
					) {
						goToIndex(0, true);
					}
					else {
						nextItem();
					}
				},
				autoplayDuration
			);
		}

		function resetAutoplay() {
			stopAutoplay();
			startAutoplay();
		}

		if (prevButton) {
			prevButton.addEventListener(
				'click',
				function () {
					previousItem();
					resetAutoplay();
				}
			);
		}

		if (nextButton) {
			nextButton.addEventListener(
				'click',
				function () {
					nextItem();
					resetAutoplay();
				}
			);
		}

		/* Swipe */

		var pointerStartX = 0;
		var pointerActive = false;
		var suppressClick = false;

		viewport.addEventListener(
			'pointerdown',
			function (event) {
				if (
					event.pointerType ===
						'mouse' &&
					event.button !== 0
				) {
					return;
				}

				pointerStartX =
					event.clientX;

				pointerActive = true;

				stopAutoplay();

				if (
					viewport.setPointerCapture
				) {
					viewport.setPointerCapture(
						event.pointerId
					);
				}
			}
		);

		viewport.addEventListener(
			'pointerup',
			function (event) {
				if (!pointerActive) {
					return;
				}

				var difference =
					event.clientX -
					pointerStartX;

				pointerActive = false;

				if (
					Math.abs(difference) >= 45
				) {
					suppressClick = true;

					if (difference < 0) {
						nextItem();
					}
					else {
						previousItem();
					}

					setTimeout(
						function () {
							suppressClick =
								false;
						},
						0
					);
				}

				startAutoplay();
			}
		);

		viewport.addEventListener(
			'pointercancel',
			function () {
				pointerActive = false;
				startAutoplay();
			}
		);

		viewport.addEventListener(
			'click',
			function (event) {
				if (!suppressClick) {
					return;
				}

				event.preventDefault();
				event.stopPropagation();
			},
			true
		);

		root.addEventListener(
			'mouseenter',
			stopAutoplay
		);

		root.addEventListener(
			'mouseleave',
			startAutoplay
		);

		root.addEventListener(
			'focusin',
			stopAutoplay
		);

		root.addEventListener(
			'focusout',
			function () {
				setTimeout(
					function () {
						if (
							!root.contains(
								document.activeElement
							)
						) {
							startAutoplay();
						}
					},
					0
				);
			}
		);

		root.addEventListener(
			'keydown',
			function (event) {
				if (
					getMaximumIndex() < 1
				) {
					return;
				}

				if (
					event.key ===
					'ArrowRight'
				) {
					event.preventDefault();

					nextItem();
					resetAutoplay();
				}

				if (
					event.key ===
					'ArrowLeft'
				) {
					event.preventDefault();

					previousItem();
					resetAutoplay();
				}
			}
		);

		document.addEventListener(
			'visibilitychange',
			function () {
				if (document.hidden) {
					stopAutoplay();
				}
				else {
					startAutoplay();
				}
			}
		);

		function handleResize() {
			clearTimeout(resizeTimer);

			resizeTimer = setTimeout(
				function () {
					applyLayout();

					goToIndex(
						Math.min(
							currentIndex,
							getMaximumIndex()
						),
						false
					);
				},
				120
			);
		}

		window.addEventListener(
			'resize',
			handleResize
		);

		if (
			typeof ResizeObserver ===
			'function'
		) {
			var resizeObserver =
				new ResizeObserver(
					handleResize
				);

			resizeObserver.observe(
				viewport
			);
		}

		if (typeof MutationObserver === 'function') {
			var orderObserver =
				new MutationObserver(
					scheduleOrderRefresh
				);

			orderObserver.observe(root, {
				childList: true,
				subtree: true,
				characterData: true
			});
		}

		setTimeout(scheduleOrderRefresh, 150);
		setTimeout(scheduleOrderRefresh, 400);
		setTimeout(scheduleOrderRefresh, 900);

		applyLayout();

		window.requestAnimationFrame(
			function () {
				goToIndex(0, false);
				startAutoplay();
			}
		);
	}

	if (!showNavigation && controls) {
		controls.hidden = true;
	}

	initializeCarousel();
})();;

css:
.text-primary{
    background: linear-gradient(180deg, #001453 0%, #1E2F7B 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.specialist-section {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 60px;
    width: 100%;
    max-width: 1440px;
    margin: 0 auto;
    padding: 0 60px;
    box-sizing: border-box;
    font-family: var(--font-family-figtree, Figtree);
}

.specialist-section__content {
    display: flex;
    flex-direction: column;
    gap: 5px;
    flex: 1;
    max-width: 849px;
}


.specialist-section__content p {
    margin-bottom: 0;
}


.specialist-section__text {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.specialist-section__title{
    margin: 0;
    padding-bottom: 16px;
    font-size: 32px;
    font-weight: 600;
    line-height: 42px;
    color: #000000;
}

.specialist-section__title *{
    font-size: 32px;
    font-weight: 600;
    line-height: 42px;
    color: #000000;
	margin-bottom: 0;
}

.specialist-section__subtitle{
    color: var(--primary-600);
}

.specialist-section__description {
    margin: 0;
    padding-bottom: 24px;
    max-width: 757px;
    font-weight: 400;
    line-height: 30px;
    color: #555555;
	font-size: 18px;
}

.specialist-section__description h2 {
    color: #555555;
    font-size: 18px !important;
    font-weight: 400 !important;
}

.specialist-section__description h3 {
    color: #555555;
    font-size: 18px !important;
    font-weight: 400 !important;
}

.specialist-section__ctas {
    display: flex;
    align-items: center;
    gap: 24px;
}

.specialist-section__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 44px;
    padding: 8px 10px;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    line-height: 26px;
    text-decoration: none;
    color: #001453;
    white-space: nowrap;
}

.specialist-section__button:hover,
.specialist-section__button:focus {
    text-decoration: none;
    color: #001453;
}

.specialist-section__button--primary {
    background: #88B9D7;
    min-width: 193px;
}

.specialist-section__button--secondary {
    background: transparent;
    min-width: 210px;
}

.specialist-section__button--secondary:hover,
.specialist-section__button--secondary:focus {
    background: rgba(136, 185, 215, 0.18);
}

.specialist-section__image {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 531px;
    height: 352px;
    background: #E0E0CD;
    border-radius: 24px;
    overflow: hidden;
}

.specialist-section__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.specialist-section.specialist-section--image-only {
    display: inline-flex;
    max-width: none;
    padding: 0;
    padding-left: 60px;
    padding-right: 60px;
    vertical-align: top;
}

.specialist-section.specialist-section--image-only .specialist-section__image {
    width: 100%;
    flex: none;
    max-height: 340px;
}

@media (min-width: 390px) and (max-width: 575px) {
    .specialist-section__ctas {
        flex-direction: column !important;
    }
}

@media (max-width: 991px) {
    .specialist-section.specialist-section--image-only {
        display: column;
        width: 100%;
        margin: 0 0 24px 0;
        padding: 0 24px;
    }
    .specialist-section.specialist-section--image-only .specialist-section__image {
        width: 100%;
        height: 260px;
    }
    .specialist-section {
        flex-direction: column;
        align-items: stretch;
        gap: 32px;
        padding: 0 24px;
    }
    .specialist-section__content {
        max-width: none;
        order: 2;
    }
    .specialist-section__image {
        order: 1;
        flex: none;
        width: 100%;
        height: 260px;
    }
    .specialist-section__title {
        font-size: 28px;
        line-height: 36px;
        padding-bottom: 16px;
    }
    .specialist-section__description {
        font-size: 16px;
        line-height: 28px;
        padding-bottom: 24px;
    }
    .specialist-section__ctas {
        flex-direction: row;
        flex-wrap: wrap;
        justify-content: center;
        gap: 16px;
    }
    .specialist-section__button {
        width: 100%;
    }
    .specialist-section__title span{
		font-size: 28px !important;	
	}
	.specialist-section__description{
		font-size: 18px !important;	
	}
}

@media (max-width: 1190px) {
    .specialist-section.specialist-section--image-only {
        display: column;
        width: 100%;
        margin: 0 0 24px 0;
        padding: 0 24px;
    }
    .specialist-section.specialist-section--image-only .specialist-section__image {
        width: 100%;
        height: 260px;
    }
    .specialist-section {
        flex-direction: column;
        align-items: stretch;
        gap: 32px;
        padding: 0 24px;
    }
    .specialist-section__content {
        max-width: none;
        order: 2;
    }
    .specialist-section__image {
        order: 1;
        flex: none;
        width: 100%;
        height: 260px;
    }
    .specialist-section__title {
        font-size: 24px !important;
        line-height: 36px;
        padding-bottom: 16px;
			padding: 0;
    }
	.specialist-section__title *{
        font-size: 24px !important;
        line-height: 36px;
        padding-bottom: 16px; 
		    margin: 0;
		    padding: 0;
    }
    .specialist-section__description {
        font-size: 16px;
        line-height: 28px;
        padding-bottom: 24px;
			margin-top: 20px
    }

    .specialist-section__content p {
        font-size: 18px !important;
    }

    .specialist-section__ctas {
        flex-direction: row;
        align-items: stretch;
        gap: 16px;
    }
    .specialist-section__button {
        width: 100%;
    }
}

