(function () {
  const customClass = configuration.customClass?.trim() || 'faq-schema-wrapper';
  const schemaId = configuration.customId?.trim() || 'faq-schema';
  const name = configuration.name?.trim() || 'FAQPage';

  function createFaqSchema() {
    const wrapper = document.querySelector('.' + customClass);
    if (!wrapper) return;

    const existing = document.getElementById(schemaId);
    if (existing) existing.remove();

    const faqItems = wrapper.querySelectorAll('.faq-item');
    const mainEntity = Array.from(faqItems)
      .map((item) => {
        const question = item
          .querySelector('.faq-question-text')
          ?.innerText?.trim();
        const answer = item
          .querySelector('.faq-answer')
          ?.innerText?.trim();
        if (!question || !answer) return null;
        return {
          "@type": "Question",
          name: question,
          acceptedAnswer: {
            "@type": "Answer",
            text: answer
          }
        };
      })
      .filter(Boolean);

    if (!mainEntity.length) return;

    const script = document.createElement("script");
    script.id = schemaId;
    script.type = "application/ld+json";
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": name,
      mainEntity
    });
    wrapper.appendChild(script);
  }

  setTimeout(createFaqSchema, 1000);

  if (window.Pagina) {
    Pagina.on('endNavigate', () => {
      setTimeout(createFaqSchema, 1000);
    });
  }
})();;

