/* =========================================================
   Fragment: Minha Área Sidebar
   Cores via CSS custom properties do themeCSS client extension
   ========================================================= */

.minha-area-sidebar {
	background-color: var(--primary-700);
	border-radius: var(--border-radius-lg);
	display: flex;
	flex-direction: column;
	min-width: 220px;
	width: 100%;
}

/* ----- Banner ----- */

/* Placeholder quando nenhuma imagem foi selecionada */
.minha-area-sidebar__banner img[src=""],
.minha-area-sidebar__banner img:not([src]) {
	background-color: var(--primary-50);
	display: block;
	min-height: 120px;
}

.minha-area-sidebar__banner {
	aspect-ratio: 4 / 2.2;
	margin: var(--spacer-3) var(--spacer-4);
	background-color: var(--absolute-0);
	border-radius: var(--border-radius);
	overflow: hidden;
	width: calc(100% - var(--spacer-4) * 2);
}

.minha-area-sidebar__banner-img {
	height: 100%;
	object-fit: cover;
	width: 100%;
}

/* ----- Drop Zone ----- */

.dropzone-menu-items {
	flex: 1;
}

#main-content {
    padding-top: 100px;
}

.figtree-p2-regular {
    font-family: var(--font-family-figtree, Figtree);
    font-size: 16px;
    font-style: normal;
    font-weight: var(--font-weight-semi-bold, 600);
}

.btn-cotacao-mobile {
    position: absolute;
    top: 46px;
    width: 100%;
    z-index: 101;
}

.base-header-dropzone {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    position: fixed;
    left: 0;
    top: 0;
    z-index: 99;
    background: transparent;
    box-shadow: var(--box-shadow);
}

.base-header-dropzone .menu-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    max-width: 1440px;
    padding: 27px 60px;
    position: relative;
    gap: 32px;
}

.base-header-dropzone .menu-logo {
    display: inline-flex;
    align-items: center;
    width: 160px;
    flex-shrink: 0;
}

.base-header-dropzone .menu-logo a {
  display: inline-block
}

.base-header-dropzone .menu-logo img {
    width: 100%;
    height: 35px;
    object-fit: contain;
}

.nav-hamburger {
    display: none;
}

.navigation-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    width: 100%;
}

.busca-mobile {
    display: none;
}

.dropzone-menu-items {
    display: inline-flex;
    align-items: center;
    height: 46px;
}

.dropzone-button-items {
    display: inline-flex;
    align-items: center;
    width: 435px;
    height: 46px;
}

.dropzone-menu-items > div,
.dropzone-menu-items lfr-drop-zone,
.dropzone-menu-items lfr-drop-zone > div,
.dropzone-button-items > div,
.dropzone-button-items lfr-drop-zone,
.dropzone-button-items lfr-drop-zone > div {
    display: inline-flex;
    width: 100%;
}

.dropzone-button-items > div {
    align-items: center;
    gap: 16px;
}

.dropzone-menu-items .page-editor__no-fragments-state,
.dropzone-button-items .page-editor__no-fragments-state {
    padding: 0 !important;
}

.dropzone-menu-items .portlet,
.dropzone-menu-items .portlet-content,
.dropzone-menu-items .portlet-content-container,
.dropzone-menu-items .portlet-body,
.dropzone-button-items .portlet,
