    gap: 16px;
}

.panel-body {
    padding: 0 !important;
}

.navigation-container ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

.navigation-container .link-group {
    position: relative;
}

.navigation-container .primary-link {
    display: flex;
    align-items: center;
    gap: 8px;
    position: relative;
    color: var(--absolute-0, #FFFFFF);
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    font-weight: var(--font-weight-bold);
    max-width: 100%;
}

.navigation-container .primary-link:hover,
.navigation-container .primary-link[aria-expanded="true"] {
    color: var(--secondary-300, #88B9D7);
    text-decoration: none;
}

.navigation-container .menu-arrow {
    width: 20px;
    height: 20px;
    display: inline-block;
    content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2220%22%20height%3D%2220%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M16.5%206.5L9.763%2013.5L3.5%206.5%22%20stroke%3D%22%2378BBDA%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E');
