    width: 16px;
    height: 16px;
    content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2220%22%20height%3D%2220%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M16.5%206.5L9.763%2013.5L3.5%206.5%22%20stroke%3D%22%2378BBDA%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E');
    transform: rotate(180deg);
}

.navigation-container .secondary-link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: relative;
    color: var(--absolute-800);
    white-space: normal;
    text-decoration: none;
    cursor: pointer;
}

.navigation-container .secondary-link:hover,
.navigation-container .secondary-link[aria-expanded="true"] {
    color: var(--secondary-300, #88B9D7);
    text-decoration: none;
}

.navigation-container .secondary-link[aria-expanded="true"] {
    font-weight: var(--font-weight-bold);
}

.navigation-container .secondary-link.has-children span:not(.submenu-arrow) {
    display: inline-flex;
}

.navigation-container .submenu-arrow {
    width: 16px;
    height: 16px;
    display: inline-block;
    content: url('data:image/svg+xml,%3Csvg%20width%3D%2216%22%20height%3D%2216%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cmask%20id%3D%22a%22%20style%3D%22mask-type%3Aalpha%22%20maskUnits%3D%22userSpaceOnUse%22%20x%3D%220%22%20y%3D%220%22%20width%3D%2216%22%20height%3D%2216%22%3E%3Cpath%20fill%3D%22%23D9D9D9%22%20d%3D%22M0%200h16v16H0z%22%2F%3E%3C%2Fmask%3E%3Cg%20mask%3D%22url(%23a)%22%3E%3Cpath%20d%3D%22m5.35%2014.666-1.183-1.183L9.65%208%204.166%202.516%205.35%201.333%2012.017%208%205.35%2014.666Z%22%20fill%3D%22%232D2D2D%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E');
    transition: transform 0.3s ease-in-out;
}

.navigation-container .secondary-link[aria-expanded="true"] .submenu-arrow {
    content: url('data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22100%25%22%20height%3D%22100%25%22%20viewBox%3D%220%200%2016.03%2016.03%22%3E%3Cg%20transform%3D%22translate(0%2016.03)%20rotate(-90)%22%3E%3Crect%20width%3D%2216.03%22%20height%3D%2216.03%22%20fill%3D%22none%22%2F%3E%3Cpath%20d%3D%22M0%2C5.611%2C5.4%2C0l5.02%2C5.611%22%20transform%3D%22translate(13.225%2010.82)%20rotate(180)%22%20fill%3D%22none%22%20stroke%3D%22%23051c65%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%20stroke-width%3D%221.5%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E');
    transform: rotate(90deg);
}

.navigation-container .tertiary-link {
    display: flex;
    align-items: center;
    position: relative;
    color: var(--absolute-800);
    text-decoration: none;
    cursor: pointer;
}

.navigation-container .tertiary-link:hover {
    color: #0435AC;
    text-decoration: none;
}

.navigation-container .submenu {
    position: absolute;
    top: 32px;
    display: flex;
    flex-direction: column;
    width: 262px;
    min-height: 112px;
    padding: 16px;
    background: var(--absolute-0);
    box-shadow: var(--box-shadow);
    border-top: 1px solid transparent;
    border-right: 1px solid transparent;
    border-left: 1px solid var(--neutral-300);
    border-bottom: 1px solid var(--neutral-300);
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
    z-index: 100;
}

.navigation-container .minha-area {
    background: var(--primary-70, #001453);
}

.navigation-container .submenu.visible {
    visibility: visible;
    opacity: 1;
}

.navigation-container .submenu ul li:last-child {
    padding-bottom: 8px;
}

.navigation-container .submenu ul li:not(:last-child) {
    padding-bottom: 20px;
}

.navigation-container .sub-submenu {
    position: absolute;
    top: 0;
    left: 260px;
    width: 262px;
    min-height: 148px;
    background: #fff;
    box-shadow: var(--box-shadow);
