 * extras que empurrariam o conteúdo para fora
 * do limite do clamp.
 */
.modulo-2__title p,
.modulo-2__title div,
.modulo-2__title span,
.modulo-2__subtitle p,
.modulo-2__subtitle div,
.modulo-2__subtitle span {
