.tabs-section {
	display: flex;
    flex-direction: column;
	border-radius: 16px;
	font-family: var(--font-family-figtree);
	margin: 0 auto;
	max-width: var(--breakpoint-desktop);
	padding: 24px 16px;
	width: 100%;
	gap: 16px;
}

.tabs-section__title{
	width: fit-content;
}

.tabs-section__title *{
	color: var(--body-color);
	font-size: 32px !important;
	font-weight: var(--font-weight-bold);
	line-height: 1.3;
	margin-bottom: 8px;
}

.tabs-section__title p{
	width: fit-content;
}

.tabs-section__title-highlight {
	color: var(--primary-700);
}
.tabs-section__subtitle {
	color: var(--neutral-500);
	font-size: 18px;
	line-height: 1.5;
	margin-bottom: 0;
	width: fit-content;
}
.tabs-section__nav {
	display: flex;
	flex-direction: row;
	align-self: end;
	width: fit-content;
	flex-shrink: 0;
	gap: 8px;
	border-radius: 8px;
	background: var(--Colour-ranges-Neutrals-neutral-200, #E5E7EB);
	padding: 4px;
}

.tabs-section__tab {
	align-items: center;
	background-color: transparent;
	border: 1px solid transparent;
	border-radius: 8px;
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	cursor: pointer;
	display: inline-flex;
	font-weight: 500;
	justify-content: center;
	line-height: 26px;
	padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
	text-align: center;
	text-decoration: none;
	white-space: nowrap;
	width: 100%;
	font-size: 14px;
	font-style: normal;
	font-weight: 600;
	line-height: 26px;
	transform: scale(1);
	transition:
		background-color 250ms ease,
		border-color 250ms ease,
		color 200ms ease,
		transform 200ms ease;
	text-wrap: wrap;
}

.tabs-section__tab:hover {
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	text-decoration: none;
	border-radius: var(--radii-radius-8, 8px);
	background: var(--Colour-ranges-Primary-primary-50, #F0F2FA);
}

.tabs-section_tab:focus,
.tabs-section_tab:focus-visible{
	border-radius: var(--radii-radius-8, 8px);
	background: var(--Colour-ranges-Primary-primary-50, #F0F2FA);
	box-shadow: 0 0 0 2px var(--Colour-ranges-Absolute-Shades-absolute-shade-0, #FFF), 0 0 0 4px var(--Colour-ranges-Primary-primary-500, #3149A4);
}

.tabs-section__tab--active {
	color: var(--Colour-ranges-Absolute-Shades-absolute-shade-0, #FFF);
	border-radius: var(--radii-radius-8, 8px);
	border-color: var(--Colour-ranges-Primary-primary-700, #001453);
	background: var(--Colour-ranges-Primary-primary-700, #001453);
	transform: scale(1.02);
}

.tabs-section__content {
	position: relative;
	display: flex;
	justify-content: center;
    align-items: center;
	align-self: stretch;
}

.tabs-section__content.background-neutral-200{
    padding: 24px;
    border-radius: var(--rounded-2, 8px) 0 var(--rounded-2, 8px) var(--rounded-2, 8px);
    background: var(--Colour-ranges-Neutrals-neutral-200, #E5E7EB);
}

/*
 * Painéis: ambos podem ficar sobrepostos durante a
 * transição (crossfade), por isso o wrapper acima
 * precisa de position: relative.
 */

.tabs-section__panel {
	display: none;
	opacity: 0;
	transform: translateY(6px);
	transition: opacity 250ms ease, transform 250ms ease;
}
.tabs-section__panel--active {
	display: block;
}
.tabs-section__panel--visible {
	opacity: 1;
	transform: translateY(0);
}

.tabs-section__panel--leaving {
	position: absolute;
	inset: 0;
	opacity: 0;
	transform: translateY(-6px);
	pointer-events: none;
}

.tabs-section__panel [data-lfr-drop-zone-id] {
	min-height: 80px;
}

@media (prefers-reduced-motion: reduce) {
	.tabs-section__panel {
		transition: none;
	}
}


@media (max-width: 768px){
	.tabs-section__nav {
		justify-self: center;
		margin-top: 24px;
	}
}

/* Tablet (768px - 1439px) */
@media (min-width: 768px) and (max-width: 1439px) {
	.tabs-section {
		padding: 24px;
	}

	.tabs-section__title *{
		font-size: 24px !important;
	}

	.tabs-section__subtitle {
		font-size: 18px;
		max-width: 620px;
	}

	.tabs-section__nav {
		justify-self: center;
		margin-top: 24px;
	}

	.tabs-section__tab {
		width: auto;
	}
}
/* Desktop (>=1440px) */
@media (min-width: 1440px) {
	.tabs-section {
		padding: 60px;
	}
	.tabs-section__header {
		display: flex;
        flex-direction: column;
		gap: 28px;
	}
	.tabs-section__header-text {
		flex: 1;
	}
	.tabs-section__header > .tabs-section__nav {
        display: flex;
        flex-direction: row;
        align-self: end;
        width: fit-content;
        flex-shrink: 0;
	}

	.tabs-section__title {
		font-size: 32px;
	}

	.tabs-section__tab {
		width: auto;
	}
}

