if (fragmentElement) {
	const tabs = Array.from(fragmentElement.querySelectorAll('.tabs-section__tab'));
	const panels = fragmentElement.querySelectorAll('.tabs-section__panel');
	const tablist = fragmentElement.querySelector('.tabs-section__nav');

	const prefersReducedMotion = window.matchMedia(
		'(prefers-reduced-motion: reduce)'
	).matches;

	const FOCUSABLE_SELECTOR =
		'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

	function panelHasFocusableContent(panel) {
		return !!panel.querySelector(FOCUSABLE_SELECTOR);
	}

	function setPanelFocusability(panel) {
		if (!panel) return;

		if (panelHasFocusableContent(panel)) {
			panel.removeAttribute('tabindex');
		}
		else {
			panel.setAttribute('tabindex', '0');
		}
	}

	function lockPanelOut(panel) {
		if (!panel) return;

		panel.removeAttribute('tabindex');
		panel.setAttribute('aria-hidden', 'true');

		if ('inert' in panel) {
			panel.inert = true;
		}
	}

	function unlockPanel(panel) {
		if (!panel) return;

		panel.removeAttribute('aria-hidden');

		if ('inert' in panel) {
			panel.inert = false;
		}
	}

	const updateOrientation = () => {
		if (!tablist) return;

		const isRow =
			window.getComputedStyle(tablist).flexDirection === 'row';

		tablist.setAttribute(
			'aria-orientation',
			isRow ? 'horizontal' : 'vertical'
		);
	};

	updateOrientation();
	window.addEventListener('resize', updateOrientation);

	function getTransitionDuration(element) {
		const value = window.getComputedStyle(element).transitionDuration;
		const seconds = parseFloat(value) || 0;
		return seconds * 1000;
	}

	function crossfadePanels(oldPanel, newPanel) {
		if (!newPanel || oldPanel === newPanel) {
			return;
		}

		if (prefersReducedMotion) {
			if (oldPanel) {
				oldPanel.classList.remove(
					'tabs-section__panel--active',
					'tabs-section__panel--visible',
					'tabs-section__panel--leaving'
				);
				oldPanel.removeAttribute('aria-hidden');
				if ('inert' in oldPanel) oldPanel.inert = false;
				oldPanel.removeAttribute('tabindex');
			}
			newPanel.classList.add(
				'tabs-section__panel--active',
				'tabs-section__panel--visible'
			);
			unlockPanel(newPanel);
			setPanelFocusability(newPanel);
			return;
		}

		newPanel.classList.add('tabs-section__panel--active');
		unlockPanel(newPanel);
		setPanelFocusability(newPanel);

		void newPanel.offsetWidth;

		requestAnimationFrame(() => {
			newPanel.classList.add('tabs-section__panel--visible');
		});

		if (oldPanel) {
			lockPanelOut(oldPanel);

			oldPanel.classList.add('tabs-section__panel--leaving');
			oldPanel.classList.remove('tabs-section__panel--visible');

			const duration = getTransitionDuration(oldPanel) || 250;
			let finished = false;

			const finish = () => {
				if (finished) return;
				finished = true;

				oldPanel.classList.remove(
					'tabs-section__panel--active',
					'tabs-section__panel--leaving'
				);
				unlockPanel(oldPanel);
			};

			oldPanel.addEventListener('transitionend', finish, {
				once: true,
			});

			setTimeout(finish, duration + 50);
		}
	}

	const activateTab = (tab) => {
		const targetId = tab.getAttribute('data-tab-target');
		const targetPanel = fragmentElement.querySelector('#' + targetId);
		const currentPanel = fragmentElement.querySelector(
			'.tabs-section__panel--active:not(.tabs-section__panel--leaving)'
		);

		if (tab.classList.contains('tabs-section__tab--active')) {
			return;
		}

		tabs.forEach((currentTab) => {
			currentTab.classList.remove('tabs-section__tab--active');
			currentTab.setAttribute('aria-selected', 'false');
		});

		tab.classList.add('tabs-section__tab--active');
		tab.setAttribute('aria-selected', 'true');

		crossfadePanels(currentPanel, targetPanel);
	};

	tabs.forEach((tab) => {
		tab.setAttribute('tabindex', '0');

		tab.addEventListener('click', (event) => {
			event.preventDefault();
			activateTab(tab);
		});

		tab.addEventListener('keydown', (event) => {
			if (event.key === ' ' || event.key === 'Spacebar' || event.key === 'Enter') {
				event.preventDefault();
				activateTab(tab);
			}
		});
	});

	const initialActivePanel = fragmentElement.querySelector(
		'.tabs-section__panel--active'
	);
	if (initialActivePanel) {
		initialActivePanel.classList.add('tabs-section__panel--visible');
		setPanelFocusability(initialActivePanel);
	}
};

