/* ============================================
   Base / Mobile (390px - 767px)
   Também serve de base para Tablet (layout igual)
   ============================================ */
.suporte-section {
	display: flex;
	flex-direction: column;
	gap: 24px;
	max-width: 1440px;
	width: 100%;
	margin: 0 auto;
	padding: 24px 20px;
	font-family: var(--font-family-figtree, "Figtree");
	background-color: transparent;
}
.suporte-section__intro {
	display: flex;
	flex-direction: column;
	gap: 8px;
}
.suporte-section__title {
	margin: 0;
	font-size: 24px;
	font-weight: 700;
	line-height: 1.3;
	color: var(--neutral-900, #1a1a1a);
}
.suporte-section__subtitle {
	margin: 0;
	font-size: 18px;
	line-height: 1.4;
	color: var(--neutral-600, #6b7280);
}
.suporte-section__cards {
	display: flex;
	flex-direction: column;
	gap: 16px;
	min-width: 0;
}
.suporte-section__card {
	display: flex;
	flex-direction: column;
	gap: 6px;
	padding: 20px;
	border-radius: var(--border-radius-lg, 12px);
	background-color: var(--neutral-50, #f5f6f8);
	min-width: 0;
	max-height: 201px;
	overflow: hidden;
}
.suporte-section__card.card-branco {
	background-color: #fff;
}
.suporte-section__icon {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 24px;
	height: 24px;
	margin-bottom: 4px;
	color: var(--neutral-800, #333333);
}
.suporte-section__icon img {
	display: block;
	width: 16px;
	height: 16px;
	object-fit: contain;
}
.suporte-section__card-title {
	display: block;
	width: 100%;
	min-width: 0;
	margin: 0;

	font-size: 16px;
	font-weight: 700;
	line-height: 1.5;
	color: var(--neutral-900, #1a1a1a);

	/* Limita o título a uma linha */
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.suporte-section__card-description {
	display: -webkit-box;
	width: 100%;
	min-width: 0;
	margin: 0;

	font-size: 14px;
	line-height: 1.5;
	color: var(--neutral-600, #6b7280);

	/* Limita a descrição a duas linhas */
	-webkit-box-orient: vertical;
	-webkit-line-clamp: 2;
	line-clamp: 2;

	overflow: hidden;
	text-overflow: ellipsis;

	/* Fallback para navegadores sem line-clamp */
	max-height: calc(14px * 1.5 * 2);
}
.suporte-section__card-link {
	margin-top: 4px;
	font-size: 14px;
	font-weight: 400;
	color: var(--secondary-500);
	text-decoration: underline;
}
/* ============================================
   Tablet (768px - 1439px)
   Mesmo layout do mobile, só ajusta respiro/paddings
   ============================================ */
@media (min-width: 768px) {
	.suporte-section {
		padding: 32px 40px;
		gap: 28px;
	}
	.suporte-section__subtitle {
		font-size: 18px;
	}
	.suporte-section__cards {
		max-width: 600px;
	}
}
/* ============================================
   Desktop (>= 1440px)
   Intro à esquerda, cards em linha à direita
   ============================================ */
@media (min-width: 1440px) {
	.suporte-section {
		flex-direction: row;
		align-items: center;
		gap: 33px;
		padding: 40px 48px;
	}
	.suporte-section__title {
		font-size: 28px;
	}
	.suporte-section__intro {
		flex: 0 0 300px;
		max-width: 300px;
	}
	.suporte-section__cards {
		flex-direction: row;
		flex: 1;
		max-width: none;
		gap: 33px;
	}
	.suporte-section__card {
		flex: 1;
		min-width: 0;
	}
}

