.logos-parceiros {
  width: 100%;
  padding: 40px 24px;
  box-sizing: border-box;
}

.logos-parceiros__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  max-width: 1320px;
  margin: 0 auto;
}

.logos-parceiros__card {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 80px;
  padding: 20px 16px;
  background: #F9F9F9;
  border-radius: 8px;
  box-sizing: border-box;
}

.logos-parceiros__img {
  display: block;
  max-width: 100%;
  max-height: 80px;
  height: auto;
  object-fit: contain;
  filter: grayscale(100%);
  opacity: 0.75;
  transition: opacity 0.2s ease, filter 0.2s ease;
}

.logos-parceiros__card:hover .logos-parceiros__img {
  filter: grayscale(0%);
  opacity: 1;
}

@media (max-width: 1023px) {
  .logos-parceiros__grid {
    grid-template-columns: repeat(6, 1fr);
    gap: 16px;
  }
}

@media (max-width: 767px) {
  .logos-parceiros__grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .logos-parceiros__card {
    height: 48px;
    padding: 12px 8px;
		width: 100px;
