const heroTitleLink = fragmentElement.querySelector('.hero-banner__link a');

if (heroTitleLink) {
	const prefix = `/${configuration.linkPrefix}/`;

	const ajustarLink = () => {
		let href = heroTitleLink.getAttribute('href');

		if (
			!href ||
			/^(https?:)?\/\//.test(href) ||
			href.startsWith('#') ||
			href.startsWith('mailto:') ||
			href.startsWith('tel:') ||
			href.startsWith(prefix)
		) {
			return;
		}

		href = href.replace(/^\/+/, '');
		heroTitleLink.setAttribute('href', `${prefix}${href}`);
	};

	ajustarLink();

	const observer = new MutationObserver(ajustarLink);

	observer.observe(heroTitleLink, {
		attributes: true,
		attributeFilter: ['href']
	});
};

