const heroTitleLink = fragmentElement.querySelector('.hero-banner__link a');

if (heroTitleLink) {
	const prefix = `/${configuration.linkPrefix}/`;

	const ajustarLink = () => {
		let href = heroTitleLink.getAttribute('href');

		if (
			!href ||
			/^(https?:)?\/\//.test(href) ||
			href.startsWith('#') ||
			href.startsWith('mailto:') ||
			href.startsWith('tel:') ||
			href.startsWith(prefix)
		) {
			return;
		}

		href = href.replace(/^\/+/, '');
		heroTitleLink.setAttribute('href', `${prefix}${href}`);
	};

	ajustarLink();

	const observer = new MutationObserver(ajustarLink);

	observer.observe(heroTitleLink, {
		attributes: true,
		attributeFilter: ['href']
	});
}
.hero-banner {
	--hero-container: 1440px;
	--hero-side-space: max(20px, calc((100vw - var(--hero-container)) / 2));
	--hero-controls-space: 20px;

	--hero-bg: #16160f;
	--hero-blue: #3c89b7;
	--hero-blue-light: #6bb8e8;

	--hero-btn-bg: #8cc4e2;
	--hero-btn-text: #061b49;
	--hero-btn-hover-bg: #061b49;
	--hero-btn-active-bg: #344bb5;

	--hero-text: #f7f4ed;
	--hero-text-muted: #f7f4ed;

	--hero-dot-active: #3c89b7;
	--hero-dot-inactive: #f7f4ed;
	--hero-dot-border: #3c89b7;

	--hero-arrow-light-bg: #eef3f8;
	--hero-arrow-dark-bg: #12263f;
	--hero-arrow-hover-bg: #12263f;
	--hero-arrow-active-bg: #8cc4e2;
	--hero-arrow-disabled-bg: #dce6f0;
	--hero-arrow-stroke-bg: #3c89b7;

	--hero-arrow-light-text: #12263f;
	--hero-arrow-dark-text: #ffffff;
	--hero-arrow-disabled-text: #ffffff;

	--hero-transition-duration: 400ms;

	position: relative;
	width: 100%;
	overflow: hidden;
	background-color: var(--hero-bg);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
}

.hero-banner * {
	box-sizing: border-box;
}

.hero-banner__viewport {
	width: 100%;
	height: 500px;
	overflow: hidden;
}

.hero-banner__track {
	display: flex;
	width: 100%;
	height: 100%;
	transition: transform var(--hero-transition-duration) ease-out;
	will-change: transform;
}

.hero-banner__track > .hero-banner__slide {
	flex: 0 0 100%;
	width: 100%;
	min-width: 100%;
	height: 100%;
}

.hero-banner__slide {
	position: relative;
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	overflow: hidden;
	background-color: var(--hero-bg);
}

.hero-banner__media {
	position: absolute;
	inset: 0;
	z-index: 0;
	width: 100%;
	height: 100%;
}

.hero-banner__bg {
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center center;
	display: block;
}

.hero-banner__overlay {
	position: absolute;
	inset: 0;
	z-index: 1;
	background: linear-gradient(90deg, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.30) 25%, rgba(0, 0, 0, 0.08) 45%, rgba(0, 0, 0, 0.00) 55%);
}

.hero-banner__content {
	position: relative;
	z-index: 2;
	width: calc(100% - (var(--hero-controls-space) * 2));
	max-width: var(--hero-container);
	margin-inline: auto;
	padding: 0;
	color: var(--hero-text);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	transform: translateY(-6px);
}

.hero-banner__title {
	margin: 0 0 24px;
	max-width: 760px;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 56px;
	font-weight: 600;
	line-height: 66px;
	letter-spacing: 0;
	color: var(--hero-text);
}

.hero-banner__title p,
.hero-banner__title h1,
.hero-banner__title h2,
.hero-banner__title h3,
.hero-banner__title div,
.hero-banner__title span {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: inherit !important;
}

.hero-banner__title strong,
.hero-banner__title b,
.hero-banner__title strong span,
.hero-banner__title b span,
.hero-banner__highlight {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: var(--hero-blue) !important;
}

.hero-banner__description {
	margin: 0 0 32px;
	max-width: 760px;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 20px;
	font-weight: 400;
	line-height: 30px;
	letter-spacing: 0;
	color: var(--hero-text-muted);
}

.hero-banner__description p,
.hero-banner__description span,
.hero-banner__description div {
	margin: 0;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
	letter-spacing: inherit !important;
	color: inherit !important;
}

.hero-banner__link {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	margin-top: 8px;
	color: var(--hero-blue-light, #6bb8e8);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 16px;
	font-weight: 600;
	line-height: 20px;
	transition: color 200ms ease-out;
}

.hero-banner__link span,
.hero-banner__link span a {
	color: inherit !important;
	font: inherit !important;
	text-decoration: none;
}

.hero-banner__link-icon {
	flex-shrink: 0;
	color: #88B9D7;
	transition: transform 200ms ease-out;
}

.hero-banner__link:hover,
.hero-banner__link:focus-within {
	color: var(--hero-btn-bg, #8cc4e2);
}

.hero-banner__link:hover span a,
.hero-banner__link:focus-within span a {
	text-decoration: underline;
}

.hero-banner__link:hover .hero-banner__link-icon,
.hero-banner__link:focus-within .hero-banner__link-icon {
	transform: translateX(3px);
}

.hero-banner__ctas {
	display: flex;
	align-items: center;
	gap: 24px;
	flex-wrap: nowrap;
	max-width: 100%;
	min-width: 0;
}

.hero-banner__btn {
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
	min-width: 0;
	max-width: 100%;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	text-decoration: none;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 16px;
	font-weight: 600;
	line-height: 20px;
	border-radius: 8px;
	border: none;
	cursor: pointer;
	transition:
		background-color 200ms ease-out,
		color 200ms ease-out,
		border-color 200ms ease-out,
		box-shadow 200ms ease-out;
}

.hero-banner__btn *,
.hero-banner__btn p,
.hero-banner__btn span {
	display: block;
	max-width: 100%;
	margin: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	color: inherit !important;
	font-family: inherit !important;
	font-size: inherit !important;
	font-weight: inherit !important;
	line-height: inherit !important;
}

.hero-banner__btn:hover,
.hero-banner__btn:focus {
	text-decoration: none;
	opacity: 1;
}

.hero-banner__btn:focus-visible {
	outline: 2px solid #ffffff;
	outline-offset: 3px;
}

.hero-banner__btn--primary {
  width: fit-content;
  min-width: 132px;
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	padding: 0 24px;
	background-color: var(--hero-btn-bg);
	color: var(--hero-btn-text);
	border: 1px solid var(--hero-btn-bg);
}

.hero-banner__btn--primary:hover,
.hero-banner__btn--primary:focus {
	background-color: var(--hero-btn-hover-bg);
	color: #ffffff;
	border-color: var(--hero-btn-hover-bg);
}

.hero-banner__btn--primary:active {
	background-color: var(--hero-btn-active-bg);
	color: #ffffff;
	border-color: var(--hero-btn-active-bg);
}

.hero-banner__btn--secondary {
	width: fit-content;
 	min-width: 132px;
	height: 44px !important;
	min-height: 44px !important;
	max-height: 44px !important;
	background: transparent;
	color: var(--hero-text);
	padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
	border: 2px solid transparent;
	transition: all 0.3s ease-out;
}

.hero-banner__btn--secondary:hover{
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
}

.hero-banner__btn--secondary:focus {
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	border-radius: var(--radii-radius-8, 8px);
	border: 2px solid var(--Colour-ranges-Primary-primary-700, #001453);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
	box-shadow: 0 0 0 2px var(--bg-white-0, #FFF), 0 0 0 4px var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
}

.hero-banner__btn--secondary:active {
	color: var(--Colour-ranges-Primary-primary-700, #001453);
	background: var(--Colour-ranges-Primary-primary-100, #DDE2F2);
}

.hero-banner__arrow {
	position: absolute;
	bottom: 36px;
	z-index: 3;
	width: 32px;
	height: 33px;
	display: flex;
	align-items: center;
	justify-content: center;
	border: 1px solid transparent;
	border-radius: 4px;
	cursor: pointer;
	padding: 0;
	opacity: 1;
	transition:
		background-color 200ms ease-out,
		color 200ms ease-out,
		border-color 200ms ease-out,
		opacity 200ms ease-out;
}

.hero-banner__arrow--prev {
	right: calc(var(--hero-controls-space) + 44px);
	background-color: var(--hero-arrow-light-bg);
	color: var(--hero-arrow-light-text);
	border-color: var(--hero-arrow-light-bg);
}

.hero-banner__arrow--next {
	right: var(--hero-controls-space);
	background-color: var(--hero-arrow-dark-bg);
	color: var(--hero-arrow-dark-text);
	border-color: var(--hero-arrow-dark-bg);
}

.hero-banner__arrow:hover,
.hero-banner__arrow:focus {
	background-color: var(--hero-arrow-hover-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-hover-bg);
	opacity: 1;
}

.hero-banner__arrow:active {
	background-color: var(--hero-arrow-active-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-active-bg);
	opacity: 1;
}

.hero-banner__arrow:disabled,
.hero-banner__arrow.is-disabled {
	background-color: var(--hero-arrow-disabled-bg);
	color: var(--hero-arrow-disabled-text);
	border-color: var(--hero-arrow-disabled-bg);
	cursor: not-allowed;
	opacity: 1;
}

.hero-banner__arrow--stroke {
	background-color: transparent;
	color: var(--hero-arrow-stroke-bg);
	border-color: var(--hero-arrow-stroke-bg);
}

.hero-banner__arrow--stroke:hover,
.hero-banner__arrow--stroke:focus {
	background-color: var(--hero-arrow-stroke-bg);
	color: #ffffff;
	border-color: var(--hero-arrow-stroke-bg);
}

.hero-banner__arrow svg {
	display: block;
	width: 8px;
	height: 14px;
}

.hero-banner__dots {
	position: absolute;
	left: var(--hero-controls-space);
	bottom: 36px;
	z-index: 3;
	display: flex;
	align-items: center;
	gap: 8px;
}

.hero-banner__dot {
	width: 10px;
	height: 10px;
	min-width: 10px;
	min-height: 10px;
	border-radius: 2px;
	border: 1px solid var(--hero-dot-border);
	background-color: var(--hero-dot-inactive);
	cursor: pointer;
	padding: 0;
	opacity: 1;
	transition:
		background-color 200ms ease-out,
		border-color 200ms ease-out,
		opacity 200ms ease-out;
}

.hero-banner__dot.is-active {
	width: 10px;
	height: 10px;
	background-color: var(--hero-dot-active);
	border-color: var(--hero-dot-active);
}

.hero-banner__arrow[hidden],
.hero-banner__dots[hidden] {
	display: none !important;
}

.hero-banner.hero-banner--edit-mode {
	overflow: hidden;
}

.hero-banner.hero-banner--edit-mode .hero-banner__viewport {
	height: 500px !important;
	min-height: 500px !important;
	overflow-y: auto;
	overflow-x: hidden;
}

.hero-banner.hero-banner--edit-mode .hero-banner__track {
	display: block;
	height: auto;
	transform: none !important;
	transition: none;
}

.hero-banner.hero-banner--edit-mode .hero-banner__slide {
	height: 500px !important;
	min-height: 500px !important;
	margin-bottom: 16px;
}

.hero-banner.hero-banner--edit-mode .hero-banner__arrow,
.hero-banner.hero-banner--edit-mode .hero-banner__dots {
	display: none !important;
}

