const heroTitleLink = fragmentElement.querySelector('.hero-banner__link a');

if (heroTitleLink) {
	const prefix = `/${configuration.linkPrefix}/`;

	const ajustarLink = () => {
		let href = heroTitleLink.getAttribute('href');

		if (
			!href ||
			/^(https?:)?\/\//.test(href) ||
			href.startsWith('#') ||
			href.startsWith('mailto:') ||
			href.startsWith('tel:') ||
			href.startsWith(prefix)
		) {
			return;
		}

		href = href.replace(/^\/+/, '');
		heroTitleLink.setAttribute('href', `${prefix}${href}`);
	};

	ajustarLink();

	const observer = new MutationObserver(ajustarLink);

	observer.observe(heroTitleLink, {
		attributes: true,
		attributeFilter: ['href']
	});
}
.hero-banner {
	--hero-container: 1440px;
	--hero-side-space: max(20px, calc((100vw - var(--hero-container)) / 2));
	--hero-controls-space: 20px;

	--hero-bg: #16160f;
	--hero-blue: #3c89b7;
	--hero-blue-light: #6bb8e8;

	--hero-btn-bg: #8cc4e2;
	--hero-btn-text: #061b49;
	--hero-btn-hover-bg: #061b49;
	--hero-btn-active-bg: #344bb5;

	--hero-text: #f7f4ed;
	--hero-text-muted: #f7f4ed;

	--hero-dot-active: #3c89b7;
	--hero-dot-inactive: #f7f4ed;
	--hero-dot-border: #3c89b7;

	--hero-arrow-light-bg: #eef3f8;
	--hero-arrow-dark-bg: #12263f;
	--hero-arrow-hover-bg: #12263f;
	--hero-arrow-active-bg: #8cc4e2;
	--hero-arrow-disabled-bg: #dce6f0;
	--hero-arrow-stroke-bg: #3c89b7;

	--hero-arrow-light-text: #12263f;
	--hero-arrow-dark-text: #ffffff;
	--hero-arrow-disabled-text: #ffffff;

	--hero-transition-duration: 400ms;

	position: relative;
	width: 100%;
	overflow: hidden;
	background-color: var(--hero-bg);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
}

.hero-banner * {
	box-sizing: border-box;
}

.hero-banner__viewport {
	width: 100%;
	height: 500px;
	overflow: hidden;
}

.hero-banner__track {
	display: flex;
	width: 100%;
	height: 100%;
	transition: transform var(--hero-transition-duration) ease-out;
	will-change: transform;
}

.hero-banner__track > .hero-banner__slide {
	flex: 0 0 100%;
	width: 100%;
	min-width: 100%;
	height: 100%;
}

.hero-banner__slide {
	position: relative;
	width: 100%;
	height: 100%;
	display: flex;
	align-items: center;
	overflow: hidden;
	background-color: var(--hero-bg);
}

.hero-banner__media {
	position: absolute;
	inset: 0;
	z-index: 0;
	width: 100%;
	height: 100%;
}

.hero-banner__bg {
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center center;
	display: block;
}

.hero-banner__overlay {
	position: absolute;
	inset: 0;
	z-index: 1;
	background: linear-gradient(90deg, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.30) 25%, rgba(0, 0, 0, 0.08) 45%, rgba(0, 0, 0, 0.00) 55%);
}

.hero-banner__content {
	position: relative;
	z-index: 2;
	width: calc(100% - (var(--hero-controls-space) * 2));
	max-width: var(--hero-container);
	margin-inline: auto;
	padding: 0;
	color: var(--hero-text);
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	transform: translateY(-6px);
}

.hero-banner__title {
	margin: 0 0 24px;
	max-width: 760px;
	font-family: var(--font-family-figtree, Figtree, sans-serif);
	font-size: 56px;
	font-weight: 600;
	line-height: 66px;
	letter-spacing: 0;
	color: var(--hero-text);
}

