.hero-banner__link:hover,
.hero-banner__link:focus-within {
	color: var(--hero-btn-bg, #8cc4e2);
}

.hero-banner__link:hover span a,
.hero-banner__link:focus-within span a {
	text-decoration: underline;
}

.hero-banner__link:hover .hero-banner__link-icon,
.hero-banner__link:focus-within .hero-banner__link-icon {
