.hero-banner__arrow {
	position: absolute;
	bottom: 36px;
	z-index: 3;
	width: 32px;
	height: 33px;
	display: flex;
	align-items: center;
	justify-content: center;
	border: 1px solid transparent;
	border-radius: 4px;
	cursor: pointer;
	padding: 0;
	opacity: 1;
	transition:
		background-color 200ms ease-out,
